const KNIGHT_TITLE='Knight · Physics for Scientists and Engineers, 5th ed., ch. 23 (non-uniform λ in the end-of-chapter problems)';
const KNIGHT_URL='https://www.pearson.com/en-us/subject-catalog/p/physics-for-scientists-and-engineers-a-strategic-approach-with-modern-physics/P200000006998/9780136956297';
// A distractor is a bare expression, or an expression with the diagnosis a student who wrote it needs to read.
// Only the diagnosed ones are `mistakes`: that list is what "Easy to confuse with" prints, under the
// promise of saying what each expression would actually describe. A bare distractor stays an option,
// and is never listed with the step's hint dressed up as its diagnosis.
type Wrong=string|{expression:string;message:string};
const makeField=(id:string,label:string,expected:string,tex:string,wrong:Wrong[],hint:string):Answer=>({id,label,expected,tex,options:[expected,...wrong.map(w=>typeof w==='string'?w:w.expression)],hint,mistakes:wrong.filter(w=>typeof w!=='string').map(w=>({expression:w.expression,message:w.message,highlight:id==='distance'?'distance':id.includes('component')?'components':'element'}))});
/** ONE QUANTITY, ONE NAME, ITS SYMBOL LAST. "Easy to confuse with" heads each group of confusions with
 * its field's label, and the same quantity was named three ways from lesson to lesson: "Projection
 * factor" six times against "Projection cos α", "Projection cos θ" and "Projection factor cos θ";
 * "x-component integrand" against "Integrand dEₓ/dy" and "Integrand in θ"; "Total x-component" against
 * "Total x-component Eₓ". Each now says what it is and ends on its symbol, as "Charge element dQ" and
 * "Element-to-P distance rᵢ" always did. The z-components keep their words only: plain text has no
 * subscript z to write E_z with.
 * AND IN THE RUN'S WORDS. The run, the board and the tour cut the charge into pieces; the labels and the
 * notes under them then spoke of "elements" and "slices", and one note used two names for one thing
 * ("One element’s vertical part … only the piece level with P"). A piece is a piece everywhere now, and
 * "Projection factor", a name the board never uses, is "The factor cos α": the board says "its part
 * along x is ΔE cos α". */
const axialField=(id:string)=>id==='ring'||id==='disk'||id==='sheet';
type Config=Omit<Problem,'steps'|'sources'|'quantity'|'geometry'> & {element:string;elementTex:string;elementWrong:Wrong[];dqWrong:Wrong[];distanceWrong:Wrong[];projectionWrong:Wrong[];kernelWrong:Wrong[];componentFields:Answer[];elementHint:string;geometryHint:string;worked:NonNullable<Step['worked']>;sources?:Problem['sources'];extraGeometry?:Answer[];extraResults?:Answer[];resultWrong?:Wrong[];};
function make(c:Config):Problem{const {element,elementTex,elementWrong,dqWrong,distanceWrong,projectionWrong,kernelWrong,componentFields,elementHint,geometryHint,worked,extraGeometry=[],extraResults=[],resultWrong,...base}=c;return{...base,quantity:'E',geometry:c.id,sources:c.sources??[source],steps:[
{kind:'origin',title:'Set the frame of reference',text:'Choose the origin and move the observation point along the stated axis.',hint:'Any origin is valid. Use the convention in the model so the coordinates and bounds agree.'},
{kind:'element',title:c.id==='disk'||c.id==='sheet'?'A surface made of rings':'From pieces to a continuum',text:c.id==='disk'||c.id==='sheet'?'Each thin annulus is a complete ring. Its area is circumference × radial width.':'Divide the charge into pieces, then let their size approach zero.',hint:elementHint,fields:[makeField('element',c.id==='disk'||c.id==='sheet'?'A ring’s area':'A piece’s length',element,elementTex,elementWrong,elementHint),makeField('dq',c.id==='disk'||c.id==='sheet'?'A ring’s charge dQ':'A piece’s charge dQ',c.dq,c.dqTex.replace(/^dQ=/,''),dqWrong,elementHint)]},
{kind:'contribution',title:c.id==='disk'||c.id==='sheet'?'Reuse the ring’s field':'The field of one piece',text:c.id==='disk'||c.id==='sheet'?'A ring already has its sideways fields cancelled. Use its axial field as the piece you add up over this surface.':'Start with the inverse-square field, then project along the coordinate axes.',hint:c.id==='disk'||c.id==='sheet'?'One whole ring contributes k z dQ/(s²+z²)^(3/2). Here dQ is that entire ring, not a point.':'Follow the piece-to-P vector. The sign tells you which way each component points.',fields:componentFields},
{kind:'symmetry',title:'Check what symmetry allows',text:c.symmetry.text,hint:c.symmetry.text},
{kind:'variable',title:'One integration variable',text:'Replace the distances and projection factors using the model. Express the integrand without its differential.',hint:geometryHint,fields:[makeField('distance',c.id==='disk'||c.id==='sheet'?'Ring-to-P distance rᵢ':'Piece-to-P distance rᵢ',c.distance,'',distanceWrong,geometryHint),makeField('projection',c.id==='semi'?'The y factor cos α':c.id==='arc'?'The factor cos θ':c.id==='axial'?'The factor along x':'The factor cos α',c.projection,'',projectionWrong,geometryHint),...extraGeometry,makeField('kernel',axialField(c.id)?'z-component integrand':`x-component integrand dEₓ/d${c.variable==='theta'?'θ':c.variable}`,c.kernel,c.kernelTex,kernelWrong,geometryHint)]},
{kind:'bounds',title:'Sweep the full distribution',text:`Choose the limits for ${c.variable==='theta'?'θ':c.variable}. Drag the two brackets on the geometry or enter the bounds.`,hint:c.id==='disk'||c.id==='sheet'?'The 2π is already in the ring area. Only the radius is left to integrate.':'Cover every piece exactly once, in the positive coordinate direction.'},
{kind:'integrate',title:'Turn the sum into an integral',text:'Integrate over the charge distribution. Expand the worked steps to see each substitution and boundary evaluation.',hint:worked[0].text,fields:[makeField('result',axialField(c.id)?'Total z-component':'Total x-component Eₓ',c.result,c.resultTex.split('=')[1]??c.resultTex,resultWrong??['0',c.result.includes('2*')?c.result.replace('2*',''):c.result+'*2'],'Evaluate the antiderivative at the upper bound minus the lower bound. Keep the vector direction.'),...extraResults],worked},
{kind:'limits',title:'Explore the physical limits',text:'Check a regime where the geometry simplifies. Compare the exact field with the limiting result.',hint:c.limits[0].explanation}
]};}
// Potential is a reduced flow: the same charge layout, no symmetry step, no projection, an optional last step that differentiates V back to E.
type VConfig=Omit<Problem,'steps'|'sources'|'quantity'> & {element:string;elementTex:string;elementWrong:Wrong[];dqWrong:Wrong[];distanceWrong:Wrong[];kernelWrong:Wrong[];elementHint:string;geometryHint:string;worked:NonNullable<Step['worked']>;sources?:Problem['sources'];resultWrong?:Wrong[];gradient?:{expected:string;tex:string;wrong:Wrong[];hint:string;coord:string;worked:NonNullable<Step['worked']>};};
function makeV(c:VConfig):Problem{const {element,elementTex,elementWrong,dqWrong,distanceWrong,kernelWrong,elementHint,geometryHint,worked,resultWrong,gradient,sources,...base}=c;const surface=c.geometry==='disk';const steps:Step[]=[
{kind:'origin',title:'Set the frame of reference',text:'Choose the origin and move the observation point along the stated axis.',hint:'Any origin is valid. Use the convention in the model so the coordinates and bounds agree.'},
{kind:'element',title:surface?'A surface made of rings':'From pieces to a continuum',text:surface?'Each thin annulus is a complete ring. Its area is circumference × radial width.':'Divide the charge into pieces, then let their size approach zero.',hint:elementHint,fields:[makeField('element',surface?'A ring’s area':'A piece’s length',element,elementTex,elementWrong,elementHint),makeField('dq',surface?'A ring’s charge dQ':'A piece’s charge dQ',c.dq,c.dqTex.replace(/^dQ=/,''),dqWrong,elementHint)]},
{kind:'contribution',title:'A scalar, not a vector',text:'Potential has no direction. One piece contributes dV = k dQ / rᵢ, a number, not an arrow.',hint:'There is no cosine and no cancellation argument. Every dV adds with the sign of its charge.',fields:[makeField('field','Contribution dV','k*dQ/ri',r`\frac{k\,dQ}{r_i}`,[{expression:'k*dQ/ri^2',message:'That is Coulomb’s field, which falls as 1/rᵢ². A potential falls as 1/rᵢ, and it is a number with no direction: no projection to take and no components to add separately. That, not the power of rᵢ, is what makes this integral the easier one.'},{expression:'k*Q/ri',message:'That puts the whole object’s charge at this one piece’s distance. One piece carries only its own dQ; Q appears once every piece has been added up.'},'dE*cos(alpha)'],'Potential is k dQ over distance, a scalar.')]},
{kind:'variable',title:'One integration variable',text:'Replace the distance using the model. Express the integrand without its differential. There is no projection factor to write.',hint:geometryHint,fields:[makeField('distance',surface?'Ring-to-P distance rᵢ':'Piece-to-P distance rᵢ',c.distance,'',distanceWrong,geometryHint),makeField('kernel','Integrand dV/d'+(c.variable==='theta'?'θ':c.variable),c.kernel,c.kernelTex,kernelWrong,geometryHint)]},
{kind:'bounds',title:'Sweep the full distribution',text:`Choose the limits for ${c.variable==='theta'?'θ':c.variable}. Drag the two brackets on the geometry or enter the bounds.`,hint:surface?'The 2π is already in the ring area. Only the radius is left to integrate.':'Cover every piece exactly once, in the positive coordinate direction.'},
{kind:'integrate',title:'Turn the sum into an integral',text:'Integrate the scalar contributions. Expand the worked steps to see each substitution and boundary evaluation.',hint:worked[0].text,fields:[makeField('result','Total potential V',c.result,c.resultTex.split('=')[1]??c.resultTex,resultWrong??['0',c.result.includes('2*')?c.result.replace('2*',''):c.result+'*2'],'Evaluate the antiderivative at the upper bound minus the lower bound. Potential is a signed scalar.')],worked},
{kind:'limits',title:'Explore the physical limits',text:'Check a regime where the geometry simplifies. Compare the exact potential with the limiting result.',hint:c.limits[0].explanation}
];if(gradient)steps.push({kind:'gradient',title:'Recover the field by differentiating',text:`The field is minus the derivative of V along the observation axis. Differentiate, and you should recover the ${gradient.coord}-component you already derived by projecting vectors.`,hint:gradient.hint,fields:[makeField('gradient',(gradient.coord==='x'?'Recovered field Eₓ':'Recovered axial field'),gradient.expected,gradient.tex,gradient.wrong,gradient.hint)],worked:gradient.worked});
return{...base,quantity:'V',sources:sources??(gradient?[vSource,gradSource]:[vSource]),steps};}
/** The far limit of a potential, written in the lesson's own distance: z on an axis, r beside a rod.
 * EACH SAYS WHY, AND HOW FAST. Six lessons' far cases were one sentence, "with total charge fixed, the
 * object's size becomes negligible", on the check a lecturer asks about most: neither why the object
 * looks like a point nor how good the point is. Each now gives its own reason and the order of its
 * error, every one checked by expanding the exact answer: (R/z)² on a ring's or a disk's axis, (L/r)²
 * beside a rod. */
const farV=(formula:string,explanation:string):Limit=>({id:'far',title:'Far away, a point charge emerges',prompt:'At distances much larger than the object, which potential is recovered?',answer:'kQ/distance',choices:['kQ/distance','kQ/distance²','A potential independent of distance'],explanation,formula,mode:'far',reference:'Point charge'});
const scalarSym={answer:'Nothing cancels; every dV adds',options:['Nothing cancels; every dV adds','The transverse contributions cancel','Both components cancel'],axis:'A scalar has no partner to cancel',axes:['A scalar has no partner to cancel','Across the x-axis','Diametrically opposite pieces'],text:'Potential is a scalar. There is no direction to cancel and no projection to take. Every piece’s dV adds, with the sign of its charge.',tex:r`V=\int dV,\quad dV=\frac{k\,dQ}{r_i}`};
// Diagnoses several lessons share, written once. Each says what the expression would describe.
/** Two lengths at right angles added as if they ran in one straight line. */
const legs=(expression:string,a:string,b:string):Wrong=>({expression,message:`${a} and ${b} lie at right angles: they are the two legs of a right triangle, not one straight run. The piece is √(${a}² + ${b}²) from P.`});
const angleIsNotLength:Wrong={expression:'dtheta',message:'An angle is not a length. The piece’s arc has length R dθ, so it carries λR dθ.'};
const chargePerAngle:Wrong={expression:'lambda*dtheta',message:'λ dθ is a charge per length times an angle, which is not a charge. The piece’s arc has length R dθ, so it carries λR dθ.'};
const wholeAngleCharge:Wrong={expression:'Q*dtheta',message:'Q is the charge of the whole curve, spread over its full angle. One piece carries only λR dθ.'};
const uniformRod=(v:'x'|'y'):Wrong=>({expression:`lambda*${v}*d${v}`,message:`λ is uniform, the same at every ${v}, so each piece carries λ d${v} wherever it sits. A factor ${v} would make the density grow along the rod.`});
const wholeRodCharge=(v:'x'|'y'):Wrong=>({expression:`Q*d${v}`,message:`Q is the whole rod’s charge. A piece of length d${v} carries λ d${v}, with λ = Q/L.`});
const innerDisk:Wrong={expression:'pi*s^2*ds',message:'πs² is the area of the whole disk inside radius s. One thin ring is a strip of length 2πs and width ds, so its area is 2πs ds.'};
const outerRing:Wrong={expression:'2*pi*R*ds',message:'R is the outer edge only. A ring of radius s has circumference 2πs, so the inner rings are shorter and carry less charge.'};
const densityTimesWidth:Wrong={expression:'sigma*ds',message:'σ is a charge per area, and ds is only a width. Times the ring’s whole area, 2πs ds, it gives a charge.'};
/** A final answer written as the logarithm of a length. "You cannot take the logarithm of a length"
 * was a rule the Unfold beside it broke twice: ∫dy/√(y² + r²) came out as ln(y + √(y² + r²)), and the
 * ramp's lower end "gave ln r". What is true is narrower -- an antiderivative's ln of a length is fixed
 * only up to a constant, the unit, which cancels between the ends; an answer has no ends to cancel it
 * -- and the Unfold now writes every logarithm of a ratio, so the rule and the working agree. */
const LOG_OF_LENGTH=(denominator:string)=>`A final answer cannot be the logarithm of a length: change metres to centimetres and it would shift by a constant. Only a pure number, such as a ratio of two lengths, has a logarithm, which is why ${denominator} sits in the denominator.`;
const ringCancels:Wrong={expression:'dE',message:'A whole ring has a partner opposite each of its points, so its sideways field is exactly zero. Only the axial part is left to add.'};
/** The total charge, misused in one piece's field. An endless line has none: "Q appears once every
 * piece has been added up" told the semi-infinite line's reader that its answer comes out in a Q its
 * setup never gives, beside the infinite line's own note that there is no Q to use. */
const WHOLE_Q='Q is the charge of the whole object. One piece carries only its own dQ; Q appears once every piece has been added up.';
const ENDLESS_Q='An endless line has no finite total charge, so there is no Q to put here. One piece carries its own dQ = λ dx, and the answer comes out in λ.';
const point=(component:Answer,second?:Answer,wholeQ=WHOLE_Q)=>[makeField('field','One piece’s field dE','k*dQ/ri^2',r`\frac{k\,dQ}{r_i^2}`,[{expression:'k*dQ/ri',message:'That falls as 1/rᵢ, the way one piece’s potential does. A field falls as 1/rᵢ²: the inverse-square law.'},{expression:'k*Q/ri^2',message:wholeQ}],'Coulomb’s field uses the tiny charge dQ and the square of its distance to P.'),component,...second?[second]:[]];
// Every lesson that spreads this writes its own explanation: why it looks like a point, and how good
// the point is (see farV).
const far:Omit<Limit,'formula'|'explanation'>={id:'far',title:'Far away, a point charge emerges',prompt:'At distances much larger than the object, which field is recovered?',answer:'kQ/distance²',choices:['kQ/distance²','A field independent of distance','A field proportional to distance'],mode:'far',reference:'Point charge'};
export const axial=make({id:'axial',number:'02',title:'Field beyond the end of a rod',short:'Line · on axis',subtitle:'P lies on the rod’s own line, past one end, so every contribution points the same way.',kind:'Uniform rod',setup:r`A uniformly charged rod runs from $x=0$ to $x=L$. Point $P$ is at $x=L+a$, a distance $a>0$ beyond the right end. The rod carries a fixed total charge $Q$, so $\lambda=Q/L$. Find the electric field at $P$.`,origin:'At the rod’s left end',alternateOrigin:'At the rod’s centre',coordinate:'P=(L+a,0)',variable:'x',variableTex:'x',density:'Q/L',densityTex:r`\lambda=Q/L`,element:'dx',elementTex:'dx',elementWrong:['L*dx','x*dx'],dq:'lambda*dx',dqTex:r`dQ=\lambda\,dx`,dqWrong:[wholeRodCharge('x'),uniformRod('x')],elementHint:'A length dx contains charge λ dx. Q is the whole rod’s charge, not a density.',distance:'L+a-x',distanceWrong:[{expression:'a+x',message:'That runs along the rod the wrong way: it puts the piece at x = L, the one right next to P, a distance L + a away. With P at L + a and the piece at x, the gap is L + a − x.'},{expression:'a',message:'a is only the gap from the rod’s near end. Every other piece is farther away, up to L + a at the far end.'}],projection:'1',projectionWrong:['cos(x)','0'],kernel:'k*lambda/(L+a-x)^2',kernelTex:r`\frac{k\lambda}{(L+a-x)^2}`,kernelWrong:[{expression:'k*lambda/(a+x)^2',message:'That measures along the rod the wrong way. With P at L + a and the piece at x, the gap is L + a − x, and that is the distance to square.'},{expression:'k*lambda/(L+a-x)',message:'That falls as 1/rᵢ: it is the integrand of the potential. A field falls as 1/rᵢ², so the distance is squared.'}],geometryHint:'P is at L + a and the piece at x. Subtract: rᵢ = L + a − x. All contributions point in +x, so the projection is 1.',integralTex:r`E_x=k\lambda\int_0^L\frac{dx}{(L+a-x)^2}`,result:'k*lambda*(1/a-1/(a+L))',resultTex:r`E_x=k\lambda\left(\frac1a-\frac1{L+a}\right)`,bounds:['0','L'],boundTex:['0','L'],componentFields:point(makeField('component','x-component dEₓ','dE','dE',['0','-dE'],'Every piece lies on the line through P, on the same side of it, so each contribution lies along x: dEₓ = dE, whatever the sign of dQ.'),makeField('component2','y-component dEᵧ','0','0',['dE','-dE'],'There is no vertical separation, so each y-component is already zero.')),symmetry:{answer:'No opposing components; all add',options:['No opposing components; all add','The x-components cancel','Both components cancel'],axis:'Collinear geometry, no pairing needed',axes:['Collinear geometry, no pairing needed','Across the y-axis','Across the x-axis'],text:'Every piece lies to the left of P. For positive charge its field points right, for negative charge left. There is no cancellation argument to make: every y-component is individually zero.',tex:r`E_y=0,\quad E_x=\int dE_x`},worked:[{text:r`Let $u=L+a-x$, so $du=-dx$ and $\int dx/u^2=-\int du/u^2=1/u$: the two minus signs cancel.`,tex:r`\int\frac{dx}{(L+a-x)^2}=\frac1{L+a-x}`},{text:r`At $x=L$ the distance is $a$; at $x=0$ it is $L+a$.`,tex:r`E_x=k\lambda\left[\frac1{L+a-x}\right]_0^L`},{text:r`Over a common denominator, $1/a-1/(L+a)=L/\bigl(a(L+a)\bigr)$, and $\lambda L=Q$. The nearer parts contribute more strongly; the result points away from a positive rod.`,tex:r`E_x=\frac{k\lambda L}{a(L+a)}=\frac{kQ}{a(L+a)}`}],limits:[{...far,explanation:'With total charge fixed, the rod’s size becomes negligible and its field approaches a point charge’s. Measured from the rod’s centre, a + L/2, the point-charge form is off only by a term of order (L/a)²; measured from the near end, a, the error falls only as L/a.',formula:r`a\gg L:\quad E_x\sim\frac{kQ}{(a+L/2)^2}`},
 // The other end of the sweep, where the potential lesson beside this one already looks: up against
 // the rod's end it looks endless, and its field is a semi-infinite line's on that line's own axis.
 {id:'near',title:'Up against the end',prompt:'As P comes up against the rod’s end, a ≪ L, which field does it approach?',answer:'kλ/a',choices:['kλ/a','kQ/a²','kλ/L'],explanation:'Close to its end the rod looks endless. In Eₓ = kλ(1/a − 1/(L + a)) the far end’s term stays finite while the near end’s kλ/a grows without bound, so the field approaches kλ/a: the field of a semi-infinite line on its own axis, a gap a beyond its end. It grows as 1/a, not as a point charge’s 1/a², because the charge is spread along the line, not gathered at one point.',formula:r`a\ll L:\quad E_x\sim\frac{k\lambda}{a}`,mode:'near',reference:'Half line, on its axis'}],link:{id:'v-rod-axial',text:'The potential beyond this same rod',from:'From the field beyond the rod: the same rod and the same P, adding numbers instead of arrows'}});
export const ring=make({id:'ring',number:'04',title:'Field on the axis of a ring',short:'Ring of charge',subtitle:'P sits on the axis, the same distance from every part of the ring.',kind:'Uniform ring',setup:r`A ring of radius $R$ carries a uniform charge $Q$, so $\lambda=Q/(2\pi R)$. It lies in the $xy$-plane. $P$ is on its central axis at $(0,0,z)$, with $z>0$. The angle $\theta$ locates a piece; $\alpha$ is its field’s angle to the $z$-axis. Find the electric field at $P$.`,origin:'At the ring’s centre',alternateOrigin:'On the circumference',coordinate:'P=(0,0,z)',variable:'theta',variableTex:r`\theta`,density:'Q/(2*pi*R)',densityTex:r`\lambda=\frac{Q}{2\pi R}`,element:'R*dtheta',elementTex:r`R\,d\theta`,elementWrong:[angleIsNotLength,{expression:'2*pi*R*dtheta',message:'2πR is the whole ring’s circumference. One piece spans only dθ of the full turn, so its length is R dθ.'}],dq:'lambda*R*dtheta',dqTex:r`dQ=\lambda R\,d\theta`,dqWrong:[chargePerAngle,wholeAngleCharge],elementHint:'An angle is not a length. A piece’s arc has length R dθ, so dQ = λ R dθ.',distance:'sqrt(R^2+z^2)',distanceWrong:[{expression:'R',message:'R is the distance from the centre to the piece, in the ring’s plane. P is lifted a height z above that plane, so each piece is √(R² + z²) from P.'},legs('R+z','R','z')],projection:'z/sqrt(R^2+z^2)',projectionWrong:[{expression:'R/sqrt(R^2+z^2)',message:'That is sin α, the part of each piece’s field across the axis. The piece opposite cancels it, which is why it never reaches the answer. Along the axis the projection is cos α = z/√(R² + z²).'},'1'],kernel:'k*lambda*R*z/(R^2+z^2)^(3/2)',kernelTex:r`\frac{k\lambda Rz}{(R^2+z^2)^{3/2}}`,kernelWrong:[{expression:'k*lambda*R/(R^2+z^2)',message:'That adds the whole of each piece’s field. Only its axial part survives the cancellation, so the factor z/√(R² + z²) belongs in the integrand.'},{expression:'k*lambda*R^2/(R^2+z^2)^(3/2)',message:'That projects with sin α = R/√(R² + z²), the sideways part that cancels. The axial projection puts z, not R, in the numerator.'}],geometryHint:'Every piece of the ring is the same distance √(R² + z²) from the axis point. The adjacent side for the z-projection is z, not R.',integralTex:r`E_z=\frac{k\lambda Rz}{(R^2+z^2)^{3/2}}\int_0^{2\pi}d\theta`,result:'k*Q*z/(R^2+z^2)^(3/2)',resultTex:r`E_z=\frac{kQz}{(R^2+z^2)^{3/2}}`,bounds:['0','2*pi'],boundTex:['0',r`2\pi`],componentFields:point(makeField('component','Axial component of dE','dE*cos(alpha)',r`dE\cos\alpha`,[{expression:'dE*sin(alpha)',message:'dE sin α is the part across the axis, the part the piece opposite cancels. Along the axis the projection is dE cos α.'},{expression:'dE',message:'The slanted field is longer than its axial part. Only dE cos α lies along the axis.'}],'The z-projection uses adjacent / hypotenuse = z/rᵢ.'),makeField('component2','Component along the piece’s outward radial axis','-dE*sin(alpha)',r`-dE\sin\alpha`,['dE*sin(alpha)','0'],'For a positive piece, the part of its field at P parallel to the ring’s plane points inward, toward the axis. Its radial projection is negative.')),symmetry:{answer:'Transverse components cancel; z adds',options:['Transverse components cancel; z adds','The z-components cancel','Every component cancels'],axis:'Diametrically opposite pieces',axes:['Diametrically opposite pieces','Across the xy-plane','No partner exists'],text:'Opposite pieces have equal distance to P. Their sideways projections cancel; their axial projections add, toward +z for positive charge and toward −z for negative.',tex:r`E_x=E_y=0,\quad E_z=\int dE_z`},worked:[{text:r`The distance and the $z$-projection do not depend on $\theta$. Pull them outside the angular integral.`,tex:r`E_z=\frac{k\lambda Rz}{(R^2+z^2)^{3/2}}\int_0^{2\pi}d\theta`},{text:r`A full turn contributes $2\pi$. Use $Q=2\pi R\lambda$.`,tex:r`E_z=\frac{k(2\pi R\lambda)z}{(R^2+z^2)^{3/2}}`},{text:r`The component $E_z$ can come out negative: reversing $z$ or $Q$ reverses it. The field vanishes at the centre.`,tex:r`E_z=\frac{kQz}{(R^2+z^2)^{3/2}}`}],limits:[{...far,explanation:'Far up the axis every piece is nearly z from P and its field points nearly along the axis, so the ring acts as its charge Q gathered at its centre. The error in that is of order (R/z)².',formula:r`z\gg R:\quad E_z\sim\frac{kQ}{z^2}`},{id:'center',title:'At the centre, the field is zero',prompt:'What is the field at z = 0?',answer:'Zero',choices:['Zero','kQ/R²','Infinite'],explanation:'At the centre each piece’s field lies flat in the ring’s plane, with no part along the axis, and the piece opposite cancels all of it. Above the centre the partners still cancel the sideways parts; it is the axial part, the fraction z/rᵢ of each field, that shrinks to zero as P comes down.',formula:r`z\to0:\quad E_z\to0`,mode:'center',reference:'Centre field'},{id:'maximum',title:'A peak between the centre and infinity',prompt:'Where is the positive axial field largest?',answer:'z = R/√2',choices:['z = R/√2','z = 0','z = R'],explanation:'Differentiating the axial field gives a factor R² − 2z², which vanishes at z = R/√2. Closer in, the pieces’ fields point more and more sideways and cancel; farther out, every piece is simply farther away.',formula:r`\frac{dE_z}{dz}=0\Rightarrow z=\frac{R}{\sqrt2}`,mode:'maximum',reference:'Maximum field'}],link:{id:'disk',text:'Build a disk from these rings',from:'From the ring: a disk is these rings, nested and added up'}});
/** One whole ring's axial field, the piece the disk and the sheet both add up. Each lesson lists the
 * confusions its own symbols allow: the disk has an outer radius R to mistake for a ring's radius s;
 * the sheet has no R at all, so its list never names one. */
const ringField=(wrong:Wrong[])=>makeField('field','Axial field of one thin ring','k*z*dQ/(s^2+z^2)^(3/2)',r`\frac{kz\,dQ}{(s^2+z^2)^{3/2}}`,[{expression:'k*dQ/(s^2+z^2)',message:'That is the size of a point charge’s field. A whole ring’s sideways parts cancel, so only its axial part, the fraction z/√(s² + z²) of it, is added.'},...wrong],'dQ is a whole ring. Use its axial field, including the z/√(s²+z²) projection, not the point-charge magnitude.');
const ringKernel=ringField([{expression:'k*R*dQ/(s^2+z^2)^(3/2)',message:'R is not this ring’s radius, and the radius is not what multiplies here. On its own axis a ring of radius s gives k z dQ/rᵢ³ with rᵢ = √(s² + z²): the z in front comes from the axial projection.'}]);
const sheetRingKernel=ringField([{expression:'k*dQ/z^2',message:'As if every ring sat straight below P: a ring of radius s is √(s² + z²) away, and only the part z/√(s² + z²) of its field points along the axis.'}]);
export const disk=make({id:'disk',number:'05',title:'Field on the axis of a disk',short:'Disk of charge',subtitle:'A disk is a set of concentric rings, so the ring’s result is the thing being summed.',kind:'Uniform disk',setup:r`A disk of radius $R$ lies in the $xy$-plane, with uniform surface density $\sigma=Q/(\pi R^2)$, and $P=(0,0,z)$ with $z>0$. Use $s$ (also written $r'$) for the radius of each thin ring. Find the electric field at $P$.`,origin:'At the disk’s centre',alternateOrigin:'On the disk’s rim',coordinate:'P=(0,0,z)',variable:'s',variableTex:'s',density:'Q/(pi*R^2)',densityTex:r`\sigma=\frac{Q}{\pi R^2}`,element:'2*pi*s*ds',elementTex:r`2\pi s\,ds`,elementWrong:[innerDisk,outerRing],dq:'sigma*2*pi*s*ds',dqTex:r`dQ=\sigma\,2\pi s\,ds`,dqWrong:['sigma*pi*s^2*ds',densityTimesWidth],elementHint:'An annulus is a narrow strip with circumference 2πs and width ds. πs² is the area of an entire inner disk, not this thin ring.',distance:'sqrt(s^2+z^2)',distanceWrong:[{expression:'sqrt(R^2+z^2)',message:'That is the distance to the outer edge only. Each ring has its own radius s, so its distance to P is √(s² + z²).'},legs('s+z','s','z')],projection:'z/sqrt(s^2+z^2)',projectionWrong:[{expression:'s/sqrt(s^2+z^2)',message:'That is sin α, the part of the field across the axis, which cancels around each ring. Along the axis the projection is z/√(s² + z²).'},'1'],kernel:'k*z*sigma*2*pi*s/(s^2+z^2)^(3/2)',kernelTex:r`\frac{2\pi k\sigma zs}{(s^2+z^2)^{3/2}}`,kernelWrong:[{expression:'2*pi*k*sigma*s/(s^2+z^2)',message:'That adds k dQ/rᵢ² whole. Around each ring the sideways parts cancel, and only the fraction z/√(s² + z²) points along the axis.'},{expression:'pi*k*sigma*z*s^2/(s^2+z^2)^(3/2)',message:'That uses πs², the area of the whole inner disk, as if it were one ring. A thin ring’s area is 2πs ds.'}],geometryHint:'s varies from ring to ring; R is only the outer edge. The angular integral is already in 2πs ds. The field keeps its axial projection.',integralTex:r`E_z=2\pi k\sigma z\int_0^R\frac{s\,ds}{(s^2+z^2)^{3/2}}`,result:'sigma/(2*eps0)*(1-z/sqrt(R^2+z^2))',resultWrong:['0',{expression:'sigma/(eps0)*(1-z/sqrt(R^2+z^2))',message:'Twice the field. 2πkσ is σ/(2ε₀), because k = 1/(4πε₀). σ/ε₀ belongs at the surface of a conductor, where all of the field is on one side.'}],resultTex:r`E_z=\frac{\sigma}{2\varepsilon_0}\left(1-\frac{z}{\sqrt{R^2+z^2}}\right)\quad(z>0)`,bounds:['0','R'],boundTex:['0','R'],componentFields:[ringKernel,makeField('component','Net transverse component of one ring','0','0',[ringCancels,'dE*sin(alpha)'],'The thin ring already includes all its opposite partners. Its transverse field is zero.')],symmetry:{answer:'Each ring’s transverse components cancel',options:['Each ring’s transverse components cancel','Opposite rings cancel the axial field','No symmetry applies'],axis:'Opposite points within each ring',axes:['Opposite points within each ring','Across the xy-plane','No partner exists'],text:'The sideways components have already cancelled within each ring. The axial contributions from different radii all add.',tex:r`E_x=E_y=0,\quad E_z=\int dE_z`},worked:[{text:r`The height $z$ is fixed while $s$ runs over the rings, so $2\pi k\sigma z$ comes outside the integral. For what is left, let $u=s^2+z^2$: with $z$ fixed, $du=2s\,ds$.`,tex:r`\begin{aligned}\int\frac{s\,ds}{(s^2+z^2)^{3/2}}&=\frac12\int u^{-3/2}du\\[1em]&=-\frac1{\sqrt{s^2+z^2}}\end{aligned}`},{text:r`At the lower bound $\sqrt{z^2}=|z|$, which is $z$ only above the disk, where $z>0$.`,tex:r`E_z=2\pi k\sigma z\left(\frac1{|z|}-\frac1{\sqrt{R^2+z^2}}\right)`},{text:r`For this model $z>0$, so $z/|z|=1$. Since $k=1/(4\pi\varepsilon_0)$, the constant in front is $2\pi k\sigma=\sigma/(2\varepsilon_0)$. Below the disk the field reverses.`,tex:r`E_z=\frac{\sigma}{2\varepsilon_0}\left(1-\frac z{\sqrt{R^2+z^2}}\right)`}],limits:[{...far,explanation:'Far up the axis every ring is nearly z from P and its field points nearly along the axis, so the disk acts as its charge Q gathered at its centre. The error in that is of order (R/z)².',formula:r`z\gg R:\quad E_z\sim\frac{kQ}{z^2}`},{id:'infinite',title:'Grow the disk into an infinite sheet',prompt:'Hold σ fixed and grow R without limit. What happens to the field?',answer:'E → σ/(2ε₀), independent of z',choices:['E → σ/(2ε₀), independent of z','E → 0','E → σ/ε₀'],explanation:'Hold σ fixed, so the charge grows with the disk; at fixed Q it would thin out and the field would fall to zero. Each new ring is farther away and its bits’ fields more sideways, so its axial field is smaller, about 2πkσz ds/s² once s ≫ z, and the sum converges to σ/(2ε₀), the same at every height. An isolated nonconducting infinite sheet has σ/(2ε₀) on each side, directed away from positive charge.',formula:r`R\to\infty\;(\sigma\text{ fixed}):\quad E_z\to\frac{\sigma}{2\varepsilon_0}`,mode:'infinite',reference:'Infinite sheet'}],link:{id:'ring',text:'Revisit the ring that makes this possible',from:'From the disk: the ring that each of its pieces is'}});
export const semi=make({id:'semi',number:'06',title:'Field above the end of a semi-infinite line',short:'Semi-infinite line',subtitle:'P sits beside the end; nothing beyond it cancels the part along the line.',kind:'Semi-infinite rod',setup:r`A uniform line charge, density $\lambda$, lies on the $x$-axis from $x=0$ to $+\infty$. The point $P=(0,r)$, with $r>0$, is on the perpendicular through the line’s end; $\alpha$ is the angle at $P$ between that perpendicular and the line to a piece. This is the rod of the lesson “Field level with the end of a rod”, grown without end and laid along $x$, so $x$ and $y$ trade places. Find the electric field at $P$.`,origin:'At the rod’s endpoint',alternateOrigin:'At point P',coordinate:'P=(0,r)',variable:'x',variableTex:'x',density:'lambda',densityTex:r`\lambda\;(\mathrm{C/m})`,element:'dx',elementTex:'dx',elementWrong:['x*dx','r*dx'],dq:'lambda*dx',dqTex:r`dQ=\lambda\,dx`,dqWrong:[{expression:'lambda*x*dx',message:'λ is uniform, the same all along the line, so each piece carries λ dx wherever it sits. A factor x would make the density grow with distance.'},'lambda/r*dx'],elementHint:'Uniform λ is charge per length. dx is the length of the tiny piece, so dQ = λ dx.',distance:'sqrt(x^2+r^2)',distanceWrong:[{expression:'r',message:'r is only the leg from P straight down to the line’s end. A piece at x is √(x² + r²) from P.'},legs('x+r','x','r')],projection:'r/sqrt(x^2+r^2)',projectionWrong:['x/sqrt(x^2+r^2)','1'],kernel:'-k*lambda*x/(x^2+r^2)^(3/2)',kernelTex:r`-\frac{k\lambda x}{(x^2+r^2)^{3/2}}`,kernelWrong:[{expression:'k*lambda*x/(x^2+r^2)^(3/2)',message:'That drops the minus sign. Every piece lies at positive x, so the vector from it to P points toward −x, and the x-integrand carries −x.'},{expression:'0',message:'The integrand is not zero on a line running both ways either; there it is odd in x, so only its integral vanishes. Here every piece sits at positive x, so the integral cannot vanish.'}],geometryHint:'The vector from (x, 0) to P = (0, r) is (−x, r). Keep its negative x sign and both component integrals: cos α = r/√(x² + r²) projects onto y, and sin α = x/√(x² + r²) onto −x.',extraGeometry:[makeField('kernel2','y-component integrand dEᵧ/dx','k*lambda*r/(x^2+r^2)^(3/2)',r`\frac{k\lambda r}{(x^2+r^2)^{3/2}}`,[{expression:'0',message:'The y-parts never cancel. P is above the line, so the vector from every piece to P points partly up, and all of their y-parts point the same way.'},'-k*lambda*r/(x^2+r^2)^(3/2)'],'For positive λ every piece’s field at P points up, so the y-integrand is positive; a negative λ makes it negative through λ itself.')],integralTex:r`E_x=-k\lambda\int_0^\infty\frac{x\,dx}{(x^2+r^2)^{3/2}}`,result:'-k*lambda/r',resultWrong:[{expression:'0',message:'That would be right for a line running both ways. With the half at negative x missing, nothing cancels the x-components.'},{expression:'-2*k*lambda/r',message:'Twice too large. 2kλ/r is the field of a whole line, both halves, along its perpendicular. Each component of this half line comes to kλ/r.'}],resultTex:r`E_x=-\frac{k\lambda}{r}`,secondaryResult:'k*lambda/r',secondaryIntegralTex:r`E_y=k\lambda\int_0^\infty\frac{r\,dx}{(x^2+r^2)^{3/2}}`,secondaryResultTex:r`E_y=\frac{k\lambda}{r},\quad |\mathbf E|=\frac{\sqrt2\,k|\lambda|}{r}`,extraResults:[makeField('result2','Total y-component Eᵧ','k*lambda/r',r`\frac{k\lambda}{r}`,[{expression:'-k*lambda/r',message:'Wrong sign. Every piece lies on the x-axis, below P, so the vector from it to P points up: Eᵧ = +kλ/r, with the sign of λ.'},'0'],'For positive λ the y-components all point up; their integral is kλ/r, which carries the sign of λ.')],bounds:['0','Infinity'],boundTex:['0',r`\infty`],componentFields:point(makeField('component','x-component dEₓ','-dE*sin(alpha)',r`-dE\sin\alpha`,[{expression:'dE*sin(alpha)',message:'The vector from a piece at +x to P points toward −x, so the x-part of dE is −dE sin α. dE carries the sign of the charge; the minus comes from the geometry.'},'0'],'The source-to-P displacement has a negative x-component. α is measured from +y.'),makeField('component2','y-component dEᵧ','dE*cos(alpha)',r`dE\cos\alpha`,[{expression:'-dE*cos(alpha)',message:'The vector from a piece on the line to P points up, +y, so the y-part of dE is +dE cos α. A negative charge flips dE itself, not this sign.'},'0'],'The vertical displacement r is positive and adjacent to α.'),ENDLESS_Q),symmetry:{answer:'Neither component cancels',options:['Neither component cancels','The x-components cancel','The y-components cancel'],axis:'No partner exists on the missing half',axes:['No partner exists on the missing half','Across the y-axis','Across the x-axis'],text:'A source at +x has no matching source at −x. For positive charge every piece contributes negative x and positive y, and for negative charge the reverse, so both components survive.',tex:r`E_x\ne0,\quad E_y\ne0`},worked:[{text:r`For $E_x$, substitute $u=x^2+r^2$, so $du=2x\,dx$ and $x\,dx$ is $du/2$: the integral is $\tfrac12\int u^{-3/2}\,du=-u^{-1/2}$.`,tex:r`\int\frac{x\,dx}{(x^2+r^2)^{3/2}}=-\frac1{\sqrt{x^2+r^2}}`},{text:r`The minus from the projection meets the minus in that antiderivative, so the bracket is $1/\sqrt{x^2+r^2}$ itself. It falls from $1/r$ at the line’s end to $0$ at infinity.`,tex:r`\begin{aligned}E_x&=k\lambda\left[\frac1{\sqrt{x^2+r^2}}\right]_0^\infty\\[1.05em]&=k\lambda\left(0-\frac1r\right)=-\frac{k\lambda}{r}\end{aligned}`},{text:r`For $E_y$, the integrand $r/(x^2+r^2)^{3/2}$ is the one a rod gives for $E_x$ when $P$ is level with its end. Substitute $x=r\tan\alpha$, so $dx=r\sec^2\alpha\,d\alpha$ and the integrand becomes $\cos\alpha\,d\alpha/r$. Its integral, $\sin\alpha/r$, is $x/(r\sqrt{x^2+r^2})$.`,tex:r`\int\frac{r\,dx}{(x^2+r^2)^{3/2}}=\frac{x}{r\sqrt{x^2+r^2}}`},{text:r`At the line’s end that is $0$; at infinity $x/\sqrt{x^2+r^2}$ tends to $1$.`,tex:r`E_y=k\lambda\left[\frac{x}{r\sqrt{x^2+r^2}}\right]_0^\infty=\frac{k\lambda}{r}`},{text:r`Combine the two components, the one along the line and the one perpendicular to it. For positive $\lambda$ the field points halfway between $+y$ and $-x$, not toward $+x$.`,tex:r`\mathbf E=\frac{k\lambda}{r}(-\hat x+\hat y),\quad |\mathbf E|=\frac{\sqrt2\,k|\lambda|}{r}`}],limits:[{id:'scale',title:'Move away without changing the direction',prompt:'If r doubles with λ fixed, what happens?',answer:'Both components halve; the direction stays put',choices:['Both components halve; the direction stays put','Both components quarter','The x-component changes sign'],explanation:'Both components scale as 1/r, so doubling r halves each of them. They stay equal in size, so the field never turns as P moves away: for positive λ it points halfway between +y and −x, and for negative λ exactly the opposite way.',formula:r`r>0:\quad|E_x|=|E_y|=\frac{k|\lambda|}{r}`,mode:'scale',reference:'|Eₓ| = |Eᵧ|'}],sources:[source,{title:'Maynooth University MP204, May exam 2020–21, Q1(b), with the lecturers’ partial solutions (pp. 8–10)',url:'https://www.pks.mpg.de/~haque/maynooth_MP204/MP204_2021s2_mainfinal_withsolns_a.pdf'}],link:{id:'endpoint',text:'Cut this line back to a rod of length L',from:'From the semi-infinite line: cut it back to a rod of length L'}});
// E_y, the component this lesson is about ("neither component cancels"), went from its integral to its
// answer in one line, through ½∫u^{-3/2}du = −u^{-1/2} and the meeting of two minus signs -- the sign
// students get wrong -- while E_x above it had five steps. Both are written: the power rule, then the
// bracket, upper end minus lower end, with the near end's larger term deciding the sign.
export const endpoint=make({id:'endpoint',number:'09',title:'Field level with the end of a rod',short:'Line · level with an end',subtitle:'P is level with one end rather than the middle, so neither component cancels.',kind:'Uniform rod',setup:r`A thin rod of length $L$ carries a uniform charge $Q$, so $\lambda=Q/L$. It stands upright on the $y$-axis, its lower end at the origin, running from $y=0$ to $y=L$. Point $P$ is on the $x$-axis at $(r,0)$, level with the rod’s lower end, with $r>0$. Find the electric field at $P$.`,origin:'At the rod’s lower end',alternateOrigin:'At the rod’s centre',coordinate:'P=(r,0)',variable:'y',variableTex:'y',density:'Q/L',densityTex:r`\lambda=\frac{Q}{L}`,element:'dy',elementTex:'dy',elementWrong:['L*dy','y*dy'],dq:'lambda*dy',dqTex:r`dQ=\lambda\,dy`,dqWrong:[wholeRodCharge('y'),uniformRod('y')],elementHint:'Linear density is charge per length. Multiply λ by the tiny length dy; Q is the whole rod’s charge, not a density.',distance:'sqrt(y^2+r^2)',distanceWrong:[{expression:'r',message:'r is only the horizontal leg. A piece at height y is √(y² + r²) from P.'},legs('y+r','y','r')],projection:'r/sqrt(y^2+r^2)',projectionWrong:[{expression:'y/sqrt(y^2+r^2)',message:'That is sin α, the vertical projection. The x-component uses cos α = r/√(y² + r²), the side adjacent to α.'},'1'],kernel:'k*lambda*r/(y^2+r^2)^(3/2)',kernelTex:r`\frac{k\lambda r}{(y^2+r^2)^{3/2}}`,kernelWrong:[{expression:'k*lambda/(y^2+r^2)',message:'That adds the whole of each piece’s field. Only cos α = r/rᵢ of it lies along x, which raises the power of the distance from two to three.'},{expression:'k*lambda*y/(y^2+r^2)^(3/2)',message:'That projects with y/rᵢ, the vertical part. The x-component projects with r/rᵢ.'}],geometryHint:'r is fixed; y locates the piece on the rod. The vector from (0, y) to P is (r, −y), so the x-projection is r/√(y²+r²) and the y-projection is negative. Keep both component integrals.',extraGeometry:[makeField('kernel2','y-component integrand dEᵧ/dy','-k*lambda*y/(y^2+r^2)^(3/2)',r`-\frac{k\lambda y}{(y^2+r^2)^{3/2}}`,[{expression:'k*lambda*y/(y^2+r^2)^(3/2)',message:'That drops the minus sign. Every piece is above P, so the vector from it to P points down, −y, and the y-integrand carries −y.'},{expression:'0',message:'The integrand is not zero on a centred rod either; there it is odd in y, so its integral vanishes. Here every piece is above P, so the integral cannot vanish.'}],'Every piece lies above P, so each vertical contribution points down. This integrand is negative for positive charge.')],integralTex:r`E_x=k\lambda\int_0^L\frac{r\,dy}{(y^2+r^2)^{3/2}}`,result:'k*Q/(r*sqrt(L^2+r^2))',resultTex:r`E_x=\frac{kQ}{r\sqrt{L^2+r^2}}`,secondaryResult:'-k*lambda*(1/r-1/sqrt(L^2+r^2))',secondaryIntegralTex:r`E_y=-k\lambda\int_0^L\frac{y\,dy}{(y^2+r^2)^{3/2}}`,secondaryResultTex:r`E_y=-k\lambda\left(\frac1r-\frac1{\sqrt{L^2+r^2}}\right)=-\frac{kQ}{L}\left(\frac1r-\frac1{\sqrt{L^2+r^2}}\right)`,extraResults:[makeField('result2','Total y-component Eᵧ','-k*lambda*(1/r-1/sqrt(L^2+r^2))',r`-k\lambda\left(\frac1r-\frac1{\sqrt{L^2+r^2}}\right)`,[{expression:'k*lambda*(1/r-1/sqrt(L^2+r^2))',message:'Wrong sign. Every piece is above P, so every vertical contribution points the same way, down for positive λ, and the sum takes the sign of −λ.'},{expression:'0',message:'Only a rod centred on P’s level sums its vertical parts to zero. Every piece here is above P, so the vertical field cannot vanish.'}],'With no partner below P to cancel them, the vertical contributions all point the same way: Eᵧ is negative for positive λ, positive for negative λ.')],bounds:['0','L'],boundTex:['0','L'],componentFields:point(makeField('component','x-component dEₓ','dE*cos(alpha)',r`dE\cos\alpha`,['dE*sin(alpha)',{expression:'dE',message:'The slanted field is longer than its horizontal part. Only dE cos α lies along x.'}],'α is the angle of the contribution below +x. The x-projection is adjacent over hypotenuse.'),makeField('component2','y-component dEᵧ','-dE*sin(alpha)',r`-dE\sin\alpha`,[{expression:'dE*sin(alpha)',message:'Every piece sits above P, so the vector from it to P points down: the y-part of dE is −dE sin α. dE carries the sign of the charge; the minus comes from the geometry.'},{expression:'0',message:'One piece’s vertical part is not zero (only the piece exactly level with P has none); even on a centred rod it cancels only against a partner below P, and here there is none.'}],'The piece sits above P, so for positive charge its field at P points down.')),symmetry:{answer:'Neither component cancels',options:['Neither component cancels','The y-components cancel','Both components cancel'],axis:'No partner exists below the rod’s end',axes:['No partner exists below the rod’s end','Across the x-axis','Across the y-axis'],text:'P is level with the rod’s lower end, not with its middle. Every piece sits above P, so for positive charge every contribution points to the right and downward (for negative charge, left and upward), and there is no piece below the axis to oppose it. Both components survive; only a centred rod earns the vertical cancellation.',tex:r`E_x\ne0,\quad E_y\ne0`},worked:[{text:r`Substitute $y=r\tan\alpha$, so $dy=r\sec^2\alpha\,d\alpha$ and $y^2+r^2=r^2\sec^2\alpha$. The integrand becomes $\cos\alpha\,d\alpha/r$, whose integral, $\sin\alpha/r$, is $y/(r\sqrt{y^2+r^2})$.`,tex:r`\begin{aligned}E_x&=k\lambda\int_0^L\frac{r\,dy}{(y^2+r^2)^{3/2}}\\[1em]&=k\lambda\left[\frac{y}{r\sqrt{y^2+r^2}}\right]_0^L\end{aligned}`},{text:r`At the lower limit, $y=0$, the antiderivative is zero, so only its value at the upper limit, $y=L$, is left. That is a fact about the antiderivative, not the rod: the pieces nearest $P$ still give the largest share of the field. With $\lambda L=Q$:`,tex:r`E_x=\frac{k\lambda L}{r\sqrt{L^2+r^2}}=\frac{kQ}{r\sqrt{L^2+r^2}}`},{text:r`There is no cancellation argument for the vertical component, so its integral has to be done. Substitute $u=y^2+r^2$, so $du=2y\,dy$ and $y\,dy$ is $du/2$. Raise the power by one and divide by the new power.`,tex:r`\begin{aligned}&\int\frac{y\,dy}{(y^2+r^2)^{3/2}}=\frac12\int u^{-3/2}\,du\\[1em]&\quad=-u^{-1/2}=-\frac1{\sqrt{y^2+r^2}}\end{aligned}`},{text:r`Upper end minus lower end: $-1/\sqrt{L^2+r^2}-(-1/r)$. The minus from the projection meets the minus in the antiderivative. The near end, $y=0$, gives the larger term, so $E_y$ has the sign of $-\lambda$: downward for a positive rod.`,tex:r`\begin{aligned}E_y&=-k\lambda\int_0^L\frac{y\,dy}{(y^2+r^2)^{3/2}}\\[1em]&=-k\lambda\left[-\frac1{\sqrt{y^2+r^2}}\right]_0^L\\[1.35em]&=-k\lambda\left(\frac1r-\frac1{\sqrt{L^2+r^2}}\right)\end{aligned}`},{text:r`Both components survive, and each can come out negative: its sign says which way it points. For positive $Q$ the field points away from the rod and below the $x$-axis.`,tex:r`\mathbf E=E_x\hat x+E_y\hat y`}],limits:[{...far,explanation:'Far away every piece is nearly r from P, so the rod acts as its charge Q gathered at one point. P is out to the side of the rod, not along it, so counting r from the rod’s end rather than its centre changes |E| only by a term of order (L/r)².',formula:r`r\gg L:\quad |\mathbf E|\sim\frac{k|Q|}{r^2}`},{id:'infinite',title:'Grow the rod into a semi-infinite line',prompt:'Hold λ fixed and let L → ∞. What does the field become?',answer:'√2 k|λ|/r, at π/4 to the axis',choices:['√2 k|λ|/r, at π/4 to the axis','2kλ/r, straight along +x','0'],explanation:'With λ fixed the rod becomes semi-infinite. Eₓ tends to kλ/r and Eᵧ to −kλ/r, equal in size, so the field settles at π/4 to the x-axis and never points straight out from the rod: halfway between +x and −y for positive λ, reversed for negative λ. The Semi-infinite line lesson lays this line along x with P above its end, so x and y trade places and the same field reads (kλ/r)(−x̂ + ŷ) there.',formula:r`L\to\infty\;(\lambda\text{ fixed}):\quad\mathbf E\to\frac{k\lambda}{r}\left(\hat x-\hat y\right)`,mode:'infinite',reference:'Semi-infinite line'}],link:{id:'semi',text:'Let this rod run to infinity',from:'From the rod level with P: let it run to infinity'}});
export const ramp=make({id:'ramp',number:'10',title:'Field of a rod with rising density',short:'Line · ramp density',subtitle:'P is level with the rod’s empty end; the charge per unit length grows from zero there to λ₀ at the top.',kind:'Non-uniform rod',setup:r`A thin rod stands upright on the $y$-axis, its lower end at the origin, from $y=0$ to $y=L$, but its charge is not spread evenly: $\lambda(y)=\lambda_0y/L$, zero at the lower end and $\lambda_0$ at the top. $P$ is on the $x$-axis at $(r,0)$, level with the empty end, with $r>0$. The total charge is $Q=\lambda_0L/2$. Find the electric field at $P$.`,origin:'At the rod’s lower end, where λ = 0',alternateOrigin:'At the rod’s upper end',coordinate:'P=(r,0)',variable:'y',variableTex:'y',density:'lambda0*y/L',densityTex:r`\lambda(y)=\lambda_0\,\frac{y}{L}`,element:'dy',elementTex:'dy',elementWrong:['L*dy','y*dy'],dq:'lambda0*y/L*dy',dqTex:r`dQ=\lambda_0\frac{y}{L}\,dy`,dqWrong:[{expression:'lambda0*dy',message:'λ₀ is the density at the far end only. At height y the density is only λ(y) = λ₀y/L, so a piece near the foot carries almost no charge.'},{expression:'Q*y/L*dy',message:'That puts the total charge Q where the density λ₀ belongs: Qy dy/L comes out in coulomb-metres, not coulombs. The density at height y is λ₀y/L, and since Q = λ₀L/2 that is 2Qy/L², so dQ = 2Qy dy/L².'}],elementHint:'The density is a function of position. Multiply the local density λ(y) = λ₀y/L, not the peak λ₀, by the tiny length dy.',distance:'sqrt(y^2+r^2)',distanceWrong:[{expression:'r',message:'r is only the horizontal leg. A piece at height y is √(y² + r²) from P.'},legs('y+r','y','r')],projection:'r/sqrt(y^2+r^2)',projectionWrong:[{expression:'y/sqrt(y^2+r^2)',message:'That is sin α, the vertical projection. The x-component uses cos α = r/√(y² + r²), the side adjacent to α.'},'1'],kernel:'k*lambda0*y*r/(L*(y^2+r^2)^(3/2))',kernelTex:r`\frac{k\lambda_0\,y\,r}{L\,(y^2+r^2)^{3/2}}`,kernelWrong:[{expression:'k*lambda0*r/(y^2+r^2)^(3/2)',message:'That is the uniform rod’s integrand with λ₀ in place of λ. The charge in each piece is λ₀(y/L) dy, so a factor y/L belongs in the integrand.'},'k*lambda0*y/(L*(y^2+r^2))'],geometryHint:'r is fixed; y locates the piece. The vector from (0, y) to P is (r, −y), so the x-projection is r/√(y²+r²) and the y-projection is negative. The density λ₀y/L rides along inside dQ.',extraGeometry:[makeField('kernel2','y-component integrand dEᵧ/dy','-k*lambda0*y^2/(L*(y^2+r^2)^(3/2))',r`-\frac{k\lambda_0\,y^2}{L\,(y^2+r^2)^{3/2}}`,[{expression:'k*lambda0*y^2/(L*(y^2+r^2)^(3/2))',message:'Every piece is above P, so the vector from it to P points down. For positive λ₀ every vertical contribution is negative, and their sum cannot come out positive.'},'0'],'The piece sits above P, so its vertical field points down for positive λ₀: one factor of y from the projection, one from the density.')],integralTex:r`E_x=\frac{k\lambda_0 r}{L}\int_0^L\frac{y\,dy}{(y^2+r^2)^{3/2}}`,result:'k*lambda0/L*(1-r/sqrt(L^2+r^2))',resultTex:r`E_x=\frac{k\lambda_0}{L}\left(1-\frac{r}{\sqrt{L^2+r^2}}\right)`,resultWrong:[{expression:'k*lambda0*L/(2*r*sqrt(L^2+r^2))',message:'That is a uniform rod carrying the same total charge Q = λ₀L/2. Total charge is not enough: this rod’s charge sits farther from P on average, so Eₓ is weaker up close. The two agree only far away.'},{expression:'k*lambda0*L/(r*sqrt(L^2+r^2))',message:'That treats λ₀ as a uniform density along the whole rod. λ₀ is only the density at the top; averaged along the rod it is λ₀/2, so the total charge is λ₀L/2.'}],secondaryResult:'-k*lambda0/L*(log((L+sqrt(L^2+r^2))/r)-L/sqrt(L^2+r^2))',secondaryIntegralTex:r`E_y=-\frac{k\lambda_0}{L}\int_0^L\frac{y^2\,dy}{(y^2+r^2)^{3/2}}`,secondaryResultTex:r`E_y=-\frac{k\lambda_0}{L}\left[\ln\frac{L+\sqrt{L^2+r^2}}{r}-\frac{L}{\sqrt{L^2+r^2}}\right]`,extraResults:[makeField('result2','Total y-component Eᵧ','-k*lambda0/L*(log((L+sqrt(L^2+r^2))/r)-L/sqrt(L^2+r^2))',r`-\frac{k\lambda_0}{L}\left[\ln\frac{L+\sqrt{L^2+r^2}}{r}-\frac{L}{\sqrt{L^2+r^2}}\right]`,[{expression:'k*lambda0/L*(log((L+sqrt(L^2+r^2))/r)-L/sqrt(L^2+r^2))',message:'Every piece is above P, so for positive λ₀ every vertical contribution points down, and a sum of negative contributions is negative.'},'0'],'The vertical integrand carries y² over rᵢ³; its antiderivative is ln((y + √(y²+r²))/r) − y/√(y²+r²).')],bounds:['0','L'],boundTex:['0','L'],componentFields:point(makeField('component','x-component dEₓ','dE*cos(alpha)',r`dE\cos\alpha`,['dE*sin(alpha)',{expression:'dE',message:'The slanted field is longer than its horizontal part. Only dE cos α lies along x.'}],'α is the angle of the contribution below +x. The x-projection is adjacent over hypotenuse.'),makeField('component2','y-component dEᵧ','-dE*sin(alpha)',r`-dE\sin\alpha`,[{expression:'dE*sin(alpha)',message:'Every piece sits above P, so the vector from it to P points down: the y-part of dE is −dE sin α. dE carries the sign of the charge; the minus comes from the geometry.'},{expression:'0',message:'One piece’s vertical part is not zero (only the piece exactly level with P has none); even on a centred rod it cancels only against a partner below P, and here there is none.'}],'The piece sits above P, so for positive charge its field at P points down.')),symmetry:{answer:'Neither component cancels',options:['Neither component cancels','The y-components cancel','Both components cancel'],axis:'No partner exists, in position or in charge',axes:['No partner exists, in position or in charge','Across the x-axis','Reflect y → L − y about the rod’s midpoint'],text:'“The y-components cancel” was true when λ was uniform and P sat on the bisector. Here both conditions fail. P is level with the lower end, so every piece sits above it with no partner below. And even if P were moved up to the midpoint, the piece at L/2 + u carries more charge than the one at L/2 − u: the reflection maps the rod onto itself but not its charge, so the two vertical arrows have different lengths. Both components survive.',tex:r`\lambda\!\left(\tfrac L2+u\right)\ne\lambda\!\left(\tfrac L2-u\right),\quad E_y\ne0`},worked:[{text:r`The $y$ inside $dQ$ makes the horizontal integral easier than the uniform case. Let $u=y^2+r^2$, so $du=2y\,dy$.`,tex:r`\begin{aligned}E_x&=\frac{k\lambda_0 r}{L}\int_0^L\frac{y\,dy}{(y^2+r^2)^{3/2}}\\[1em]&=\frac{k\lambda_0 r}{L}\left[-\frac1{\sqrt{y^2+r^2}}\right]_0^L\end{aligned}`},{text:r`At the lower limit the bracket is $-1/r$, so subtracting it adds $1/r$. Factor $r$ into the bracket. With $Q=\lambda_0L/2$ this approaches $kQ/r^2$ far away, but up close $E_x$ is weaker than a uniform rod of the same $Q$, because its charge sits farther away.`,tex:r`\begin{aligned}E_x&=\frac{k\lambda_0 r}{L}\left(\frac1r-\frac1{\sqrt{L^2+r^2}}\right)\\[1em]&=\frac{k\lambda_0}{L}\left(1-\frac{r}{\sqrt{L^2+r^2}}\right)\end{aligned}`},{text:r`The vertical integrand carries $y^2$: one $y$ from the projection and one from the density. Put $y=r\tan\alpha$, as for a uniform rod’s $E_x$: $dy=r\sec^2\alpha\,d\alpha$ and $(y^2+r^2)^{3/2}=r^3\sec^3\alpha$, so the integrand is $\tan^2\alpha\cos\alpha\,d\alpha$. Since $\tan^2\alpha=\sec^2\alpha-1$, that is $(\sec\alpha-\cos\alpha)\,d\alpha$. Integrate, then return to the triangle, where $\sec\alpha+\tan\alpha=\bigl(y+\sqrt{y^2+r^2}\bigr)/r$ and $\sin\alpha=y/\sqrt{y^2+r^2}$.`,tex:r`\begin{aligned}&\int\frac{y^2\,dy}{(y^2+r^2)^{3/2}}\\[1em]&\quad=\int(\sec\alpha-\cos\alpha)\,d\alpha\\[0.8em]&\quad=\ln(\sec\alpha+\tan\alpha)-\sin\alpha\\[0.3em]&\quad=\ln\frac{y+\sqrt{y^2+r^2}}{r}-\frac{y}{\sqrt{y^2+r^2}}\end{aligned}`},{text:r`Evaluate from $0$ to $L$. The logarithm’s argument is a ratio of lengths, a pure number, and at the lower end, $y=0$, the whole antiderivative is zero.`,tex:r`\begin{aligned}E_y&=-\frac{k\lambda_0}{L}\bigg[\ln\frac{L+\sqrt{L^2+r^2}}{r}\\&\phantom{{}=-\frac{k\lambda_0}{L}\bigg[}-\frac{L}{\sqrt{L^2+r^2}}\bigg]\end{aligned}`}],limits:[{...far,prompt:'Far away, which point charge does this rod imitate?',answer:'kQ/r² with Q = λ₀L/2',choices:['kQ/r² with Q = λ₀L/2','kλ₀L/r²','2kλ₀/r'],explanation:'Far away the rod’s length stops mattering; only its total charge does. That is Q = λ₀L/2, not λ₀L: the density rises evenly from zero to λ₀, so it averages λ₀/2 along the rod. With λ₀L in its place the far field would come out twice too large.',formula:r`r\gg L:\quad |\mathbf E|\sim\frac{k|Q|}{r^2},\quad Q=\frac{\lambda_0L}{2}`},{id:'moment',title:'The vertical field remembers where the charge sits',prompt:'Far away, Eᵧ falls as 1/r³. Which length fixes its coefficient?',answer:'The centre of charge, ȳ = 2L/3',choices:['The centre of charge, ȳ = 2L/3','The rod’s midpoint, y = L/2','The rod’s full length, L'],explanation:'Far away Eᵧ approaches −kQ·ȳ/r³, falling as 1/r³, where ȳ = 2L/3 is the centre of charge, the charge-weighted average height: the density rises toward the top, so the average sits above the middle. A uniform rod of the same length would put it at L/2. The vertical field, along the rod, is a first moment: it knows how the charge is arranged, not just how much there is.',formula:r`r\gg L:\quad E_y\sim-\frac{kQ\,\bar y}{r^3},\qquad \bar y=\frac{2L}{3}`,mode:'moment',reference:'First-moment field'}],link:{id:'endpoint',text:'Compare with the uniform rod in the same position',from:'From the rod with rising density: the same place, with the charge spread evenly'},sources:[source,{title:KNIGHT_TITLE,url:KNIGHT_URL}]});
export const arc=make({id:'arc',number:'07',title:'Field at the centre of an arc',short:'Arc of charge',subtitle:'P sits at the centre, the same distance from every part of the arc. The opening angle decides what survives.',kind:'Uniform arc',setup:r`An arc of radius $R$ sits symmetrically about the $+x$ axis and spans $-\varphi/2\le\theta\le+\varphi/2$, with $0<\varphi\le2\pi$. $P$ is the centre of curvature. The total charge $Q$ is fixed as $\varphi$ changes, so $\lambda=Q/(R\varphi)$. Find the electric field at $P$.`,origin:'At the centre of curvature',alternateOrigin:'At the arc’s midpoint',coordinate:'P=(0,0)',variable:'theta',variableTex:r`\theta`,density:'Q/(R*phi)',densityTex:r`\lambda=\frac{Q}{R\varphi}`,element:'R*dtheta',elementTex:r`R\,d\theta`,elementWrong:[angleIsNotLength,{expression:'phi*R*dtheta',message:'φ is the opening of the whole arc. One piece spans only dθ, so its length is R dθ.'}],dq:'lambda*R*dtheta',dqTex:r`dQ=\lambda R\,d\theta`,dqWrong:[chargePerAngle,wholeAngleCharge],elementHint:'A tiny arc length is R dθ. λ multiplies that length; φ describes the entire arc, not each piece.',distance:'R',distanceWrong:[{expression:'sqrt(R^2+theta^2)',message:'θ is an angle, not a length, so it cannot sit beside R² under a root. Every piece of the arc is exactly R from its centre.'},'2*R'],projection:'cos(theta)',projectionWrong:[{expression:'sin(theta)',message:'sin θ projects onto y, and those parts cancel in pairs across the axis. The x-component uses cos θ, and with a minus sign: the direction from the piece to the centre is −(cos θ, sin θ).'},'1'],kernel:'-k*lambda*cos(theta)/R',kernelTex:r`-\frac{k\lambda}{R}\cos\theta`,kernelWrong:[{expression:'k*lambda*cos(theta)/R',message:'That drops the minus sign. From a piece to the centre is −(cos θ, sin θ), so the x-integrand carries −cos θ for every piece.'},'-k*lambda/R^2'],geometryHint:'Every piece is exactly R from the centre. Its field points inward, with x projection −cos θ. Substitute dQ = λR dθ: one factor of R cancels.',integralTex:r`E_x=-\frac{k\lambda}{R}\int_{-\varphi/2}^{\varphi/2}\cos\theta\,d\theta`,result:'-2*k*lambda*sin(phi/2)/R',resultWrong:[{expression:'0',message:'Only the full circle, φ = 2π, gives zero. On a shorter arc the y-components cancel in pairs, but the x-components do not. Every piece within a quarter turn of +x gives an x-part of one sign, and only an arc wider than a semicircle has pieces giving the other, never enough to cancel until the circle closes.'},{expression:'-k*lambda*sin(phi/2)/R',message:'Half the answer. sin θ from −φ/2 to φ/2 is sin(φ/2) − sin(−φ/2): sine is odd, so the lower bound adds a second sin(φ/2).'}],resultTex:r`E_x=-\frac{2k\lambda}{R}\sin\frac\varphi2`,bounds:['-phi/2','phi/2'],boundTex:[r`-\varphi/2`,r`\varphi/2`],componentFields:point(makeField('component','x-component dEₓ','-dE*cos(theta)',r`-dE\cos\theta`,[{expression:'dE*cos(theta)',message:'The vector from the piece at angle θ to the centre is −(cos θ, sin θ), so the x-part of dE is −dE cos θ at every θ. It points toward −x for pieces within a quarter turn of +x, and toward +x for pieces beyond that, which only an arc wider than a semicircle has. dE carries the sign of the charge; the minus comes from the geometry.'},'dE*sin(theta)'],'At the centre a positive piece’s field points away from it, back across the arc: the x projection is −dE cos θ.'),makeField('component2','y-component dEᵧ','-dE*sin(theta)',r`-dE\sin\theta`,[{expression:'dE*sin(theta)',message:'The vector from a piece above the axis to the centre points down, so the y-part of dE is −dE sin θ. Its partner at −θ gives +dE sin θ, and the pair cancels.'},'0'],'For an upper piece and positive charge, the field at the centre points down. Its opposite partner will cancel this component.')),symmetry:{answer:'The y-components cancel; x adds',options:['The y-components cancel; x adds','The x-components cancel','Neither component cancels'],axis:'Reflect θ to −θ across the x-axis',axes:['Reflect θ to −θ across the x-axis','Across the y-axis','No partner exists'],text:'The pieces at +θ and −θ have opposing y-components and equal x-components. For the full circle, the remaining x contributions cancel too.',tex:r`E_y=0,\quad E_x=\int dE_x`},worked:[{text:r`The distance is the constant $R$. Integrate the angular projection: $\int\cos\theta\,d\theta=\sin\theta$.`,tex:r`E_x=-\frac{k\lambda}{R}[\sin\theta]_{-\varphi/2}^{\varphi/2}`},{text:r`Sine is odd. Subtracting the lower bound doubles $\sin(\varphi/2)$.`,tex:r`E_x=-\frac{2k\lambda}{R}\sin\frac\varphi2`},{text:r`Using the total charge $Q=\lambda R\varphi$ gives the equivalent form. A semicircle has $\varphi=\pi$, where $\sin(\varphi/2)=1$.`,tex:r`\begin{aligned}E_x&=-\frac{2kQ}{R^2\varphi}\sin\frac\varphi2\\[0.95em]E_x(\pi)&=-\frac{2kQ}{\pi R^2}\end{aligned}`}],limits:[{id:'full',title:'Close the arc into a full circle',prompt:'When φ reaches 2π, what is the field at P?',answer:'Zero',choices:['Zero','2kλ/R','kQ/R²'],explanation:'Here the total charge Q stays fixed as the arc opens, so λ = Q/(Rφ) and Eₓ = −2kQ sin(φ/2)/(R²φ). A short arc is nearly a point charge, kQ/R². As it opens, the same charge spreads round the circle: more of each piece’s field points sideways, where its partner across the axis cancels it, and past a semicircle some pieces point back the other way. So the field only falls. Once the circle closes, every piece has a partner directly opposite: sin(φ/2) = sin π = 0. At fixed λ the field would instead grow until the semicircle before falling.',formula:r`\varphi\to2\pi\;(Q\text{ fixed}):\quad E_x=-\frac{2kQ}{R^2}\,\frac{\sin(\varphi/2)}{\varphi}\to0`,mode:'full',reference:'Full-circle centre'},{id:'half',title:'A semicircle, built from point charges',prompt:'For φ = π, what is Eₓ?',answer:'−2kQ/(πR²)',choices:['−2kQ/(πR²)','−kQ/(πR²)','0'],explanation:'Open the arc to a semicircle, φ = π, and build it from N point charges. One, at the arc’s middle, gives kQ/R², stronger than the semicircle’s field by a factor π/2: its whole field lies along the axis, while the semicircle’s pieces off to the side count only in part. As N grows the pieces spread round the arc, their fields fan out, and their sum closes on the integral. That integral is the semicircle’s field: sin(φ/2) = 1, so Eₓ = −2kλ/R, with the semicircle’s own density λ = Q/(πR): Eₓ = −2kQ/(πR²). For positive Q the field points away from the arc, toward −x.',formula:r`\varphi=\pi:\quad E_x=-\frac{2k\lambda}{R}=-\frac{2kQ}{\pi R^2}`,mode:'half',reference:'Half-ring field'}],link:{id:'v-arc',text:'The potential at this same centre, which the opening angle never changes',from:'From the arc’s field: the same centre, where the potential ignores the opening angle'}});
// "The upper term tends to zero. The lower term is −1/|z|", then 2πkσ z/|z|: a student who added the
// lower term got −2πkσ, a field pointing at a positive sheet. The subtraction 0 − (−1/|z|) is written,
// and 2πkσz is said to come outside, as the disk's Unfold says it.
// THE SHEET'S WORKING STANDS ON ITS OWN. It opened "What is left is the disk's integral … its
// antiderivative is −1/√(s² + z²)": a reader who came straight to the sheet had nothing to follow.
// The u-substitution is written out here. And it ended on |z|, sgn(z) and a Gauss pillbox under a
// model that puts P at z > 0 and builds every field lesson from Coulomb's law: the bracket is now
// evaluated at that z, and below the sheet is one sentence.
export const sheet=make({...disk,id:'sheet',number:'08',title:'Field of an infinite sheet',short:'Infinite sheet',subtitle:'Cut the sheet into rings by their angle below P. Lift P and each angle’s ring grows, making the same field at P: the field never changes.',kind:'Infinite nonconducting sheet',setup:r`A uniform, isolated, nonconducting infinite sheet lies in the $xy$-plane with uniform surface density $\sigma$. $P$ is at $z>0$. Build it from rings of radius $s$, extending from $0$ to infinity. The sheet itself, $z=0$, is left out: the field jumps across it. Find the electric field at $P$.`,origin:'In the sheet, directly below P',alternateOrigin:'At point P',coordinate:'P=(0,0,z)',variable:'s',variableTex:'s',density:'sigma',densityTex:r`\sigma\;(\mathrm{C/m^2})`,element:'2*pi*s*ds',elementTex:r`2\pi s\,ds`,elementWrong:[innerDisk,{expression:'ds',message:'ds is only the ring’s width. Its area is that width times the ring’s length, the circumference 2πs.'}],dqWrong:[densityTimesWidth,'sigma*pi*s^2*ds'],elementHint:'Each complete ring has area 2πs ds. The sheet consists of rings at every radius; do not integrate the angle a second time.',distanceWrong:[{expression:'z',message:'z reaches only the point of the sheet straight below P. A ring of radius s is √(s² + z²) away.'},legs('s+z','s','z')],projectionWrong:['1',{expression:'s/sqrt(s^2+z^2)',message:'That is sin α, the part of the field across the axis, which cancels around each ring. Along the axis the projection is z/√(s² + z²).'}],kernelWrong:[{expression:'2*pi*k*sigma*s/(s^2+z^2)',message:'That adds k dQ/rᵢ² whole. Around each ring the sideways parts cancel, and only the fraction z/√(s² + z²) points along the axis.'},{expression:'k*z*sigma/(s^2+z^2)^(3/2)',message:'That drops the ring’s circumference, 2πs. Each ring carries σ · 2πs ds, so rings farther out carry more charge.'}],geometryHint:'For each radius s, the distance is √(s²+z²), and the axial projection is z/√(s²+z²). The ring circumference grows with s.',componentFields:[sheetRingKernel,makeField('component','Net transverse component of one ring','0','0',[ringCancels,'dE*cos(alpha)'],'Each whole ring’s sideways components cancel.')],integralTex:r`E_z=2\pi k\sigma\int_0^\infty\frac{zs\,ds}{(s^2+z^2)^{3/2}}`,result:'sigma/(2*eps0)',resultWrong:['0',{expression:'sigma/(eps0)',message:'Twice the field. An isolated sheet sends half of σ/ε₀ out of each face: σ/(2ε₀) on either side. σ/ε₀ belongs at the surface of a conductor, where all of the field is on one side.'}],resultTex:r`E_z=\frac{\sigma}{2\varepsilon_0}\quad(z>0)`,bounds:['0','Infinity'],boundTex:['0',r`\infty`],worked:[{text:r`$2\pi k\sigma z$ is the same for every ring: the height $z$ is fixed while $s$ runs over the rings. So it comes outside the integral.`,tex:r`E_z=2\pi k\sigma z\int_0^\infty\frac{s\,ds}{(s^2+z^2)^{3/2}}`},{text:r`Let $u=s^2+z^2$. With $z$ fixed, $du=2s\,ds$, so $s\,ds$ is $du/2$. Raise the power by one and divide by the new power.`,tex:r`\begin{aligned}\int\frac{s\,ds}{(s^2+z^2)^{3/2}}&=\frac12\int u^{-3/2}\,du\\[1em]&=-\frac1{\sqrt{s^2+z^2}}\end{aligned}`},{text:r`Upper end minus lower end. As $s\to\infty$ the term tends to $0$; at $s=0$ it is $-1/\sqrt{z^2}=-1/z$, since $z>0$. So the bracket is $0-(-1/z)=1/z$.`,tex:r`\begin{aligned}E_z&=2\pi k\sigma z\left[-\frac1{\sqrt{s^2+z^2}}\right]_0^\infty\\[1.05em]&=2\pi k\sigma z\left(0+\frac1z\right)\end{aligned}`},{text:r`The $z$ in front cancels the $1/z$ from the bracket, and no $z$ is left: every height above the sheet feels the same field, pointing away from a positive sheet. Since $k=1/(4\pi\varepsilon_0)$, $2\pi k\sigma=\sigma/(2\varepsilon_0)$. Below the sheet the mirror image of this argument turns the field round.`,tex:r`E_z=2\pi k\sigma=\frac{\sigma}{2\varepsilon_0}`}],limits:[{id:'scale',title:'Distance changes. The field does not.',prompt:'If you double z above this infinite sheet, what happens to E?',answer:'It stays the same',choices:['It stays the same','It halves','It quarters'],explanation:'The ideal sheet has no edge or length scale. Its field is independent of distance. A real finite disk approximates this only when z is small relative to its radius.',formula:r`E_z(2z)=E_z(z)=\frac{\sigma}{2\varepsilon_0}`,mode:'scale',reference:'σ/(2ε₀)'},{id:'infinite',title:'Recover the sheet from a growing disk',prompt:'Which quantity must stay fixed as the disk radius grows?',answer:'Surface density σ',choices:['Surface density σ','Total charge Q','The disk circumference'],explanation:'An infinite sheet has a finite density and unbounded total charge. Keeping Q fixed would dilute the charge and send the field to zero.',formula:r`R\to\infty\;(\sigma\text{ fixed}):\quad E_z\to\frac{\sigma}{2\varepsilon_0}`,mode:'infinite',reference:'Infinite sheet'}],link:{id:'disk',text:'Return to a disk with an edge',from:'From the infinite sheet: give it back its edge'},sources:[source,{title:'OpenStax · University Physics 2, §6.3, Gauss’s law and a charged plane',url:'https://openstax.org/books/university-physics-volume-2/pages/6-3-applying-gausss-law'}]});
/** The infinite line's own check: its field falls as 1/r, not 1/r², and a rod of length L is the
 * thing it is the limit of. The rod case was once the bisector's, word for word -- "dividing by L
 * reveals 2kλ/r" repeats the derivation rather than checking it, and on the angular route the
 * lesson had never mentioned an L. Here L is defined where it is used. The scale case's formula is an
 * equation at two distances, E_x(r) = 2kλ/r and E_x(2r) = kλ/r: it was written "r → 2r: 2kλ/r → kλ/r", where the
 * arrow meant "becomes" beside every other case's arrow for "tends to". */
const INFINITE_SCALE:Limit={id:'scale',title:'Double r and E halves',prompt:'If r doubles with λ fixed, what happens to E?',answer:'It halves: E falls as 1/r',choices:['It halves: E falls as 1/r','It quarters, as for a point charge','It stays the same, as for a sheet'],explanation:'From every distance the line fills the same angle at P, and the stretch of it inside any fixed angle grows in proportion to r: its charge grows as r while the inverse square shrinks its field as r², so the field falls only as 1/r and never steepens to a point charge’s 1/r². So |E| times r never changes: doubling r halves the field.',formula:r`E_x(r)=\frac{2k\lambda}{r},\quad E_x(2r)=\frac{2k\lambda}{2r}=\frac{k\lambda}{r}`,mode:'scale',reference:'2kλ/r'};
const INFINITE_FROM_ROD:Limit={id:'infinite',title:'Near the middle of a long rod',prompt:'A rod of length L has the same density λ. What does its field at distance r from its middle become as L grows?',answer:'E → 2kλ/r',choices:['E → 2kλ/r','E → kQ/r² with Q fixed','E → 0'],explanation:'No real line is endless. A rod of length L with this density λ has the field kλL/(r√((L/2)² + r²)) at distance r from its middle. As L grows far past r it tends to 2kλ/r: this line’s field is what any long rod gives near its middle.',formula:r`L\to\infty\;(\lambda\text{ fixed}):\quad E_x\to\frac{2k\lambda}{r}`,mode:'infinite',reference:'Infinite line'};
export function infiniteFrom(b:Problem,path='angular'):Problem{const angular=path==='angular';return{...b,id:'infinite',geometry:'infinite',number:'03',title:'Field of an infinite line',short:'Infinite line',subtitle:'Hold the charge per unit length fixed and let the rod run on without ending.',kind:'Infinite uniform line',origin:'At the point on the line nearest P',alternateOrigin:'Anywhere else along the line',setup:r`An infinite line of uniform density $\lambda$ lies on the $y$-axis, and $P=(r,0)$ with $r>0$. Find the electric field at $P$. `+(angular?r`Use $y=r\tan\alpha$ to sweep the whole line with $-\pi/2<\alpha<\pi/2$.`:r`Start with a rod of length $L$, hold $\lambda$ fixed, then let $L$ grow without bound.`),density:'lambda',densityTex:r`\lambda\;(\mathrm{C/m})`,variable:angular?'alpha':'y',variableTex:angular?r`\alpha`:'y',distance:angular?'r/cos(alpha)':b.distance,projection:angular?'cos(alpha)':b.projection,kernel:angular?'k*lambda*cos(alpha)/r':b.kernel,kernelTex:angular?r`\frac{k\lambda}{r}\cos\alpha`:b.kernelTex,integralTex:angular?r`E_x=\frac{k\lambda}{r}\int_{-\pi/2}^{\pi/2}\cos\alpha\,d\alpha`:r`E_x=\lim_{L\to\infty}k\lambda\int_{-L/2}^{L/2}\frac{r\,dy}{(y^2+r^2)^{3/2}}`,result:'2*k*lambda/r',resultTex:r`E_x=\frac{2k\lambda}{r}=\frac{\lambda}{2\pi\varepsilon_0r}`,bounds:angular?['-pi/2','pi/2']:b.bounds,boundTex:angular?[r`-\pi/2`,r`\pi/2`]:b.boundTex,steps:b.steps.map((s,i)=>i===5?{kind:'bounds',title:angular?'Sweep the entire infinite line':'Set the finite rod’s bounds first',text:angular?'The two ends of the angular sweep approach −π/2 and +π/2. They represent y → −∞ and y → +∞; there are no finite endpoints.':'Use −L/2 to +L/2 for the finite rod. The next step takes L to infinity while λ stays fixed.',hint:angular?'Because y = r tan α, the whole y-axis is covered exactly once between −π/2 and +π/2.':'L is the full rod length, so the centred endpoints are −L/2 and +L/2.'}:i===4&&angular?{kind:'variable',title:'Let an angle sweep an infinite line',text:'Substitute y = r tan α. The change in the differential is just as important as the change in the distance.',hint:'dy = r sec²α dα and rᵢ = r sec α. Two powers of sec α cancel before integration.',fields:[makeField('distance','Piece-to-P distance rᵢ','r/cos(alpha)',r`r\sec\alpha`,[{expression:'r',message:'r reaches only the point of the line nearest P. The piece at angle α is r sec α away.'},{expression:'r*tan(alpha)',message:'r tan α is where the piece sits along the line, y, not how far it is from P. The distance is the hypotenuse, r sec α.'}],'The hypotenuse is r/cos α. The angle stays between −π/2 and +π/2.'),makeField('projection','The factor cos α','cos(alpha)',r`\cos\alpha`,[{expression:'sin(alpha)',message:'sin α projects along the line, and those parts cancel in pairs above and below P. The x-component uses cos α.'},'1'],'α is measured at P, between the perpendicular out to the line and the line to the piece.'),makeField('jacobian','Change of variable dy/dα','r/cos(alpha)^2',r`r\sec^2\alpha`,[{expression:'r',message:'That keeps only r. Differentiating y = r tan α gives dy = r sec²α dα, and those two powers of sec α are what cancel two powers of the distance.'},'1/cos(alpha)'],'Differentiate y = r tan α: dy = r sec²α dα. Omitting this factor changes the integral.'),makeField('kernel','x-component integrand dEₓ/dα','k*lambda*cos(alpha)/r',r`\frac{k\lambda\cos\alpha}{r}`,[{expression:'k*lambda*cos(alpha)^3/r^2',message:'That leaves out the change of variable. With dy = r sec²α dα, the two powers of sec α cancel cos²α and one power of r, leaving kλ cos α/r.'},'k*lambda/r^2'],'Multiply by the Jacobian r sec²α. The integrand reduces to kλ cos α/r.')]}:i===6?{kind:'integrate',title:'Evaluate the whole line',text:angular?'The remaining angular integral is elementary.':'Now take L → ∞ while keeping charge per length λ fixed.',hint:angular?'The antiderivative of cos α is sin α. Its values at the bounds are +1 and −1.':'Divide numerator and denominator by L. Q = λL grows with L; holding Q fixed would give zero.',fields:[makeField('result','Total x-component Eₓ','2*k*lambda/r',r`2k\lambda/r`,[{expression:'k*lambda/r',message:'Half the answer: that is the perpendicular part of one half’s field. Each half also has a part along the line, which the other half cancels. The two halves’ perpendicular parts add: Eₓ = 2kλ/r.'},'k*lambda/r^2'],'Both halves of the infinite line contribute. The result is 2kλ/r.')],worked:angular?[{text:r`Substitute $y=r\tan\alpha$ and $dy=r\sec^2\alpha\,d\alpha$.`,tex:r`\begin{aligned}\frac{r\,dy}{(r^2+y^2)^{3/2}}&=\frac{r^2\sec^2\alpha}{r^3\sec^3\alpha}d\alpha\\[1em]&=\frac{\cos\alpha}{r}d\alpha\end{aligned}`},{text:r`The entire $y$-axis maps to $-\pi/2$ to $+\pi/2$.`,tex:r`E_x=\frac{k\lambda}{r}[\sin\alpha]_{-\pi/2}^{\pi/2}`},{text:r`Upper minus lower is $1-(-1)=2$.`,tex:r`E_x=\frac{2k\lambda}{r}=\frac{\lambda}{2\pi\varepsilon_0r}`}]:[{text:r`This is the integral of a rod on its bisector, done by $y=r\tan\alpha$ in the lesson “Field on the bisector of a rod”: $\int r\,dy/(y^2+r^2)^{3/2}=y/(r\sqrt{y^2+r^2})$. Evaluate it between $\pm L/2$, keeping $\lambda$ rather than a fixed $Q$.`,tex:r`\begin{aligned}E_x(L)&=k\lambda\left[\frac{y}{r\sqrt{y^2+r^2}}\right]_{-L/2}^{L/2}\\&=\frac{k\lambda L}{r\sqrt{(L/2)^2+r^2}}\end{aligned}`},{text:r`Divide numerator and denominator by $L$.`,tex:r`E_x(L)=\frac{k\lambda}{r\sqrt{1/4+(r/L)^2}}`},{text:r`Let $L$ grow at fixed $\lambda$. The square root tends to $1/2$.`,tex:r`\lim_{L\to\infty}E_x(L)=\frac{2k\lambda}{r}`}]}:i===0?{...s,hint:angular?'Every point on an endless line looks like every other, so the origin goes where it simplifies the sweep: the point nearest P. The angle then runs −π/2 to +π/2.':'Every point on an endless line looks like every other. Centre the finite rod first, so the bounds stay symmetric while L grows.'}:i===4?{...s,fields:s.fields?.map(f=>f.id==='kernel'?{...f,hint:'Multiply Coulomb’s field by cos α and substitute dQ = λ dy.'}:f.id==='projection'?{...f,label:'The factor cos α',hint:'The adjacent side is r; α is measured at P from the perpendicular to the line.',mistakes:[{expression:'y/sqrt(y^2+r^2)',message:'That is sin α, the part along the line, which cancels in pairs above and below P. The x-component uses cos α = r/√(y² + r²).',highlight:'components'}]}:f)}:i===1?{...s,fields:s.fields?.map(f=>f.id==='dq'?{...f,hint:'The line’s density λ is given directly. Multiply it by a tiny length dy.',mistakes:[{expression:'Q*dy',message:'An endless line has no finite total charge, so there is no Q to use. The density λ is what is given: the piece carries λ dy.',highlight:'element'}]}:f)}:i===2?{...s,text:'Use Coulomb’s law and project the field onto the axes. α is the angle at P between the perpendicular to the line and the line to the selected piece.',hint:'The x-component lies adjacent to α. For positive charge the vertical component of a piece above the axis points down, so it carries a minus sign.',fields:[s.fields![0],makeField('component','x-component dEₓ','dE*cos(alpha)',r`dE\cos\alpha`,['dE*sin(alpha)',{expression:'dE',message:'dE is the whole slanted arrow. Only dE cos α of it lies along x.'}],'Project onto x: adjacent / hypotenuse.'),makeField('component2','y-component dEᵧ','-dE*sin(alpha)',r`-dE\sin\alpha`,['dE*sin(alpha)','0'],'For a piece above the axis and positive charge, the field at P points down; its partner below cancels it.')]}:i===7?{...s,hint:'From every distance the line fills the same angle at P, but the stretch of it inside any fixed angle grows in proportion to your distance. Its charge grows as r while the inverse square shrinks its field as r², which is why this field falls as 1/r and never steepens to 1/r².'}:s),limits:[INFINITE_SCALE,INFINITE_FROM_ROD],link:{id:'bisector',text:'Compare with a finite line',from:'From the infinite line: cut it back to a rod with two ends'}};}
export const vRing=makeV({id:'v-ring',geometry:'ring',number:'11',title:'Potential on the axis of a ring',short:'Ring · potential',subtitle:'Every piece is the same distance from P. The integral is a scalar, and the axial field falls out of one derivative.',kind:'Uniform ring',setup:r`A ring of radius $R$ carries a uniform charge $Q$, so $\lambda=Q/(2\pi R)$. It lies in the $xy$-plane. Find the potential at $P=(0,0,z)$, with $z>0$, relative to infinity. The angle $\theta$ locates a piece.`,origin:'At the ring’s centre',alternateOrigin:'On the circumference',coordinate:'P=(0,0,z)',variable:'theta',variableTex:r`\theta`,density:'Q/(2*pi*R)',densityTex:r`\lambda=\frac{Q}{2\pi R}`,dq:'lambda*R*dtheta',dqTex:r`dQ=\lambda R\,d\theta`,distance:'sqrt(R^2+z^2)',projection:'1',kernel:'k*lambda*R/sqrt(R^2+z^2)',kernelTex:r`\frac{k\lambda R}{\sqrt{R^2+z^2}}`,integralTex:r`V=\frac{k\lambda R}{\sqrt{R^2+z^2}}\int_0^{2\pi}d\theta`,result:'k*Q/sqrt(R^2+z^2)',resultTex:r`V=\frac{kQ}{\sqrt{R^2+z^2}}`,bounds:['0','2*pi'],boundTex:['0',r`2\pi`],element:'R*dtheta',elementTex:r`R\,d\theta`,elementWrong:[angleIsNotLength,{expression:'2*pi*R*dtheta',message:'2πR is the whole ring’s circumference. One piece spans only dθ of the full turn, so its length is R dθ.'}],dqWrong:[chargePerAngle,wholeAngleCharge],elementHint:'An angle is not a length. A piece’s arc has length R dθ, so dQ = λ R dθ.',distanceWrong:[{expression:'z',message:'z is the distance to the centre, not to the charge. Every piece sits a distance √(R² + z²) away, and none of them is at the centre.'},'R'],kernelWrong:[{expression:'k*lambda*R*z/(R^2+z^2)^(3/2)',message:'That is the field integrand, with the extra z/rᵢ from the axial projection. Potential has no projection, so neither that cosine nor the extra power of rᵢ belongs in it.'},'k*lambda*R/(R^2+z^2)'],geometryHint:'Every piece of the ring is the same distance √(R² + z²) from the axis point. There is no cosine to write; the integrand does not depend on θ.',resultWrong:[{expression:'k*Q/z',message:'That is a point charge at the centre: right only far away, z ≫ R. Every piece is √(R² + z²) from P, not z.'},{expression:'0',message:'Potential is a scalar, and every bit of this ring carries charge of the same sign, so the piece opposite adds its own k dQ/rᵢ instead of cancelling it. Potentials cancel only between charges of opposite sign, as on a dipole’s bisector, where V is zero though E is not.'},{expression:'k*Q/R',message:'That is V at the centre, z = 0, where every piece is R away. At height z each piece is √(R² + z²) away, so |V| is smaller.'}],symmetry:scalarSym,worked:[{text:r`The distance does not depend on $\theta$. Pull it outside the angular integral.`,tex:r`V=\frac{k\lambda R}{\sqrt{R^2+z^2}}\int_0^{2\pi}d\theta`},{text:r`A full turn contributes $2\pi$. Use $Q=2\pi R\lambda$.`,tex:r`V=\frac{k(2\pi R\lambda)}{\sqrt{R^2+z^2}}`},{text:r`The potential is even in $z$ and finite at the centre, where the field vanishes.`,tex:r`V=\frac{kQ}{\sqrt{R^2+z^2}},\qquad V(0)=\frac{kQ}{R}`}],limits:[farV(r`z\gg R:\quad V\sim\frac{kQ}{z}`,'Far up the axis every piece is nearly z from P, so the ring acts as its charge Q gathered at its centre: V approaches kQ/z, one power of distance softer than the field. The error in that is of order (R/z)².'),{id:'center',title:'At the centre the field vanishes; the potential does not',prompt:'What is the potential at the centre of the ring, where E = 0?',answer:'kQ/R, finite and nonzero',choices:['kQ/R, finite and nonzero','Zero, because E = 0','Infinite'],explanation:'E = 0 means V is flat there, not zero. V(z) is even in z, so dV/dz at z = 0 vanishes automatically, while V(0) = kQ/R stays finite.',formula:r`z\to0:\quad V\to\frac{kQ}{R}\ne0`,mode:'center',reference:'Centre potential'}],link:{id:'ring',text:'The field you already built by projecting vectors',from:'From the ring’s potential: the field, built by adding arrows'},gradient:{coord:'z',expected:'k*Q*z/(R^2+z^2)^(3/2)',tex:r`\frac{kQz}{(R^2+z^2)^{3/2}}`,hint:'Differentiate V = kQ(R² + z²)^(−1/2): the power −½ brings down a minus, and the chain rule a factor 2z. That minus, times the minus in E = −dV/dz, leaves a field along +z above a positive ring.',wrong:[{expression:'-k*Q*z/(R^2+z^2)^(3/2)',message:'The minus sign in E = −dV/dz is not cosmetic. Fields point from high potential to low; without it the field would point toward a positive charge.'},{expression:'-dV/dz',message:'−dV/dz is the recipe, not its result. Differentiated, the 1/√(R² + z²) in V brings down a factor of z.'},'k*Q/(R^2+z^2)'],worked:[{text:r`On the axis, symmetry leaves $\mathbf E$ with only its axial part, so that part is the whole field there. $V$ known only on the axis cannot give $\mathbf E$ off it. $V$ is even in $z$, and differentiating its reciprocal square root brings down a factor of $z$.`,tex:r`\begin{aligned}\frac{dV}{dz}&=-\tfrac12\,kQ\,(R^2+z^2)^{-3/2}\cdot 2z\\[0.75em]&=-\frac{kQz}{(R^2+z^2)^{3/2}}\end{aligned}`},{text:r`The field is minus that derivative. For $z>0$ a positive ring’s field points away along $+z$: the same axial field you derived by projecting vectors.`,tex:r`E_z=-\frac{dV}{dz}=\frac{kQz}{(R^2+z^2)^{3/2}}`}]}});
// THE POTENTIALS WRITE THE STEPS THEIR FIELD TWINS WRITE. The disk's potential opened on a bare
// antiderivative, with no 2πkσ coming outside and no [√(s² + z²)] bracket; the rod's on its axis went
// from ∫(−du/u) between turned-round ends straight to ln((L + a)/a), the step where its own confusion
// list diagnoses ln(a/(L + a)). Each now has the constant out, the ends turned round and the bracket.
// The rod's logarithm is taken as ln(u/a), a log of a ratio, so that no line takes the log of a length.
export const vDisk=makeV({id:'v-disk',geometry:'disk',number:'12',title:'Potential on the axis of a disk',short:'Disk · potential',subtitle:'Add up the potentials of concentric rings of charge, then differentiate once to recover the disk’s field on its axis.',kind:'Uniform disk',setup:r`A disk of radius $R$ lies in the $xy$-plane, with uniform surface density $\sigma=Q/(\pi R^2)$. Find the potential at $P=(0,0,z)$, with $z>0$, relative to infinity. Use $s$ for the radius of each thin ring.`,origin:'At the disk’s centre',alternateOrigin:'On the disk’s rim',coordinate:'P=(0,0,z)',variable:'s',variableTex:'s',density:'Q/(pi*R^2)',densityTex:r`\sigma=\frac{Q}{\pi R^2}`,dq:'sigma*2*pi*s*ds',dqTex:r`dQ=\sigma\,2\pi s\,ds`,distance:'sqrt(s^2+z^2)',projection:'1',kernel:'k*sigma*2*pi*s/sqrt(s^2+z^2)',kernelTex:r`\frac{2\pi k\sigma s}{\sqrt{s^2+z^2}}`,integralTex:r`V=2\pi k\sigma\int_0^R\frac{s\,ds}{\sqrt{s^2+z^2}}`,result:'sigma/(2*eps0)*(sqrt(R^2+z^2)-z)',resultTex:r`V=\frac{\sigma}{2\varepsilon_0}\left(\sqrt{R^2+z^2}-z\right)\quad(z>0)`,bounds:['0','R'],boundTex:['0','R'],element:'2*pi*s*ds',elementTex:r`2\pi s\,ds`,elementWrong:[innerDisk,outerRing],dqWrong:['sigma*pi*s^2*ds',densityTimesWidth],elementHint:'An annulus is a narrow strip with circumference 2πs and width ds. πs² is the area of an entire inner disk, not this thin ring.',distanceWrong:[{expression:'sqrt(R^2+z^2)',message:'That is the distance to the outer edge only. Each ring has its own radius s, so its distance to P is √(s² + z²).'},legs('s+z','s','z')],kernelWrong:[{expression:'2*pi*k*sigma*z*s/(s^2+z^2)^(3/2)',message:'That is the field integrand. Potential has no z/rᵢ projection and falls as 1/rᵢ, so the power in the denominator is 1/2, not 3/2.'},'k*sigma*pi*s^2/sqrt(s^2+z^2)'],geometryHint:'s varies from ring to ring; R is only the outer edge. The angular integral is already in 2πs ds. There is no axial cosine in dV.',resultWrong:[{expression:'sigma/(2*eps0)',message:'That is the field of an infinite sheet. Hold σ fixed and grow R: V diverges. An infinite sheet has no finite potential relative to infinity, only ΔV.'},{expression:'k*Q/z',message:'That is the point-charge potential, the far limit, valid only for z ≫ R. At finite z the exact result is σ/(2ε₀) · (√(R² + z²) − z).'},'sigma/(2*eps0)*sqrt(R^2+z^2)'],symmetry:scalarSym,worked:[{text:r`$2\pi k\sigma$ is the same for every ring: the height $z$ is fixed while $s$ runs over the rings. So it comes outside the integral.`,tex:r`V=2\pi k\sigma\int_0^R\frac{s\,ds}{\sqrt{s^2+z^2}}`},{text:r`Let $u=s^2+z^2$. With $z$ fixed, $du=2s\,ds$, so $s\,ds$ is $du/2$ and the integral is $\int du/(2\sqrt u)=\sqrt u$.`,tex:r`\int\frac{s\,ds}{\sqrt{s^2+z^2}}=\sqrt{s^2+z^2}`},{text:r`Upper end minus lower end. At the lower end $\sqrt{z^2}=|z|$, and for this model $z>0$, so the lower term is $z$.`,tex:r`\begin{aligned}V&=2\pi k\sigma\Bigl[\sqrt{s^2+z^2}\Bigr]_0^R\\[0.75em]&=2\pi k\sigma\left(\sqrt{R^2+z^2}-|z|\right)\\[0.7em]&=2\pi k\sigma\left(\sqrt{R^2+z^2}-z\right)\end{aligned}`},{text:r`Since $k=1/(4\pi\varepsilon_0)$, the constant $2\pi k$ is $1/(2\varepsilon_0)$. This holds above the disk, $z>0$; below it, write $|z|$ in place of $z$. As $R\to\infty$ at fixed $\sigma$ the potential diverges, even though the field converges.`,tex:r`V=\frac{\sigma}{2\varepsilon_0}\left(\sqrt{R^2+z^2}-z\right)`}],limits:[farV(r`z\gg R:\quad V\sim\frac{kQ}{z}`,'Far up the axis every ring is nearly z from P, so the disk acts as its charge Q gathered at its centre: V approaches kQ/z, one power of distance softer than the field. The error in that is of order (R/z)².'),{id:'center',title:'On the disk the potential is finite',prompt:'What is the potential at the centre of the disk, z = 0?',answer:'σR/(2ε₀) = 2kQ/R',choices:['σR/(2ε₀) = 2kQ/R','Zero','Infinite, as it would be on a point charge'],explanation:'The field of a disk jumps across z = 0; the potential is the integral of that field and stays finite: V(0) = σR/(2ε₀) = 2kQ/R.',formula:r`z\to0:\quad V\to\frac{\sigma R}{2\varepsilon_0}=\frac{2kQ}{R}`,mode:'center',reference:'Centre potential'},{id:'infinite',title:'An infinite sheet has no finite V relative to infinity',prompt:'Hold σ fixed and grow R without limit. What happens to V?',answer:'V diverges; an infinite sheet has only ΔV',choices:['V diverges; an infinite sheet has only ΔV','V → σ/(2ε₀), like the field','V → 0'],explanation:'The field of a growing disk converges to σ/(2ε₀). The potential does not: V ∼ σR/(2ε₀), so |V| grows without end, and V keeps the sign of σ. That is why an infinite sheet’s potential is only ever quoted as a difference, ΔV = −σ Δz/(2ε₀).',formula:r`R\to\infty\;(\sigma\text{ fixed}):\quad V\sim\frac{\sigma R}{2\varepsilon_0},\quad |V|\to\infty`,mode:'infinite',reference:'Divergent potential'}],link:{id:'disk',text:'The field this potential differentiates back to',from:'From the disk’s potential: the field it differentiates back to'},gradient:{coord:'z',expected:'sigma/(2*eps0)*(1-z/sqrt(R^2+z^2))',tex:r`\frac{\sigma}{2\varepsilon_0}\left(1-\frac{z}{\sqrt{R^2+z^2}}\right)`,hint:'Differentiate V = σ/(2ε₀) · (√(R² + z²) − z) for z > 0. The minus in E = −dV/dz recovers the disk field you already derived from rings.',wrong:[{expression:'-sigma/(2*eps0)*(1-z/sqrt(R^2+z^2))',message:'E = −dV/dz. The extra minus would point the field toward a positive disk.'},{expression:'sigma/(2*eps0)',message:'That is the infinite-sheet field, the R → ∞ limit of this derivative, not the finite disk.'},'sigma/eps0*(1-z/sqrt(R^2+z^2))'],worked:[{text:r`On the axis, symmetry leaves $\mathbf E$ with only its axial part, so that part is the whole field there. $V$ known only on the axis cannot give $\mathbf E$ off it. Above the disk, where $z>0$, differentiate the square root and the lone $z$ one term at a time.`,tex:r`\frac{dV}{dz}=\frac{\sigma}{2\varepsilon_0}\left(\frac{z}{\sqrt{R^2+z^2}}-1\right)`},{text:r`For $z>0$ the field is minus that slope, $E_z=-dV/dz$, since a field points the way $V$ falls fastest: it is the disk’s axial field, the result of the lesson “Field on the axis of a disk”.`,tex:r`E_z=\frac{\sigma}{2\varepsilon_0}\left(1-\frac{z}{\sqrt{R^2+z^2}}\right)`}]}});
export const vArc=makeV({id:'v-arc',geometry:'arc',number:'13',title:'Potential at the centre of an arc',short:'Arc · potential',subtitle:'Every part of the arc is the same distance from P, so at a fixed total charge the potential does not depend on the opening angle.',kind:'Uniform arc',setup:r`An arc of radius $R$ sits symmetrically about the $+x$ axis and spans $-\varphi/2\le\theta\le+\varphi/2$, with $0<\varphi\le2\pi$. $P$ is the centre of curvature. The total charge $Q$ is fixed as $\varphi$ changes, so $\lambda=Q/(R\varphi)$. Find $V$ at $P$ relative to infinity.`,origin:'At the centre of curvature',alternateOrigin:'At the arc’s midpoint',coordinate:'P=(0,0)',variable:'theta',variableTex:r`\theta`,density:'Q/(R*phi)',densityTex:r`\lambda=\frac{Q}{R\varphi}`,dq:'lambda*R*dtheta',dqTex:r`dQ=\lambda R\,d\theta`,distance:'R',projection:'1',kernel:'k*lambda',kernelTex:r`k\lambda`,integralTex:r`V=k\lambda\int_{-\varphi/2}^{\varphi/2}d\theta`,result:'k*Q/R',resultTex:r`V=\frac{kQ}{R}`,bounds:['-phi/2','phi/2'],boundTex:[r`-\varphi/2`,r`\varphi/2`],element:'R*dtheta',elementTex:r`R\,d\theta`,elementWrong:[angleIsNotLength,{expression:'phi*R*dtheta',message:'φ is the opening of the whole arc. One piece spans only dθ, so its length is R dθ.'}],dqWrong:[chargePerAngle,wholeAngleCharge],elementHint:'A tiny arc length is R dθ. λ multiplies that length; φ describes the entire arc, not each piece.',distanceWrong:[{expression:'sqrt(R^2+theta^2)',message:'θ is an angle, not a length, so it cannot sit beside R² under a root. Every piece of the arc is exactly R from its centre.'},'2*R'],kernelWrong:[{expression:'-k*lambda*cos(theta)/R',message:'That is the field integrand, with a cosine from the projection onto x. Potential has no direction, so the cosine is not there, and one power of R already cancelled in k dQ/R.'},'k*lambda*cos(theta)'],geometryHint:'Every piece is exactly R from the centre. dV = k dQ / R = k λ dθ, independent of θ. The opening angle φ never enters the integrand.',resultWrong:[{expression:'0',message:'The field of a full ring is zero at the centre; the potential is not. E = 0 means V is flat there, not zero. V = kQ/R for every φ, including 2π.'},{expression:'-2*k*lambda*sin(phi/2)/R',message:'That is this arc’s electric field. Potential does not see the opening angle: a quarter-circle, a semicircle and a full ring with the same Q all give V = kQ/R.'},{expression:'k*Q/R^2',message:'That has the units of a field, not a potential. Potential falls as 1/R, one power softer than the field.'}],symmetry:scalarSym,worked:[{text:r`The distance is the constant $R$, and $dQ=\lambda R\,d\theta$, so one factor of $R$ cancels.`,tex:r`dV=\frac{k\lambda R\,d\theta}{R}=k\lambda\,d\theta`},{text:r`Integrate over the arc. What remains is the total angle, $\varphi$.`,tex:r`V=k\lambda\varphi`},{text:r`With $Q=\lambda R\varphi$, the potential is $kQ/R$ for every opening angle: a semicircle, a quarter-circle and a complete ring included.`,tex:r`V=\frac{kQ}{R}`}],limits:[{id:'full',title:'Close the arc: the field vanishes, the potential does not',prompt:'When φ reaches 2π, what is the potential at P?',answer:'kQ/R, the same as for any other φ',choices:['kQ/R, the same as for any other φ','Zero, because the field is zero','2kλ/R'],explanation:'Opening the arc at fixed Q moves its charge around the circle but never nearer to P, so V = kQ/R at every φ. The field does not keep still: the pieces come to face each other, and when the circle closes each has a partner opposite, so E = 0 there. That means V is level at the centre, not zero: it sits at kQ/R, which has the sign of Q.',formula:r`\varphi=2\pi:\quad V=\frac{kQ}{R},\quad E=0`,mode:'full',reference:'Full-circle potential'}],link:{id:'arc',text:'The same arc’s field vanishes when the circle closes; its potential does not',from:'From the arc’s potential: the field, which vanishes when the circle closes'}});
export const vRodBisector=makeV({id:'v-rod-bisector',geometry:'bisector',number:'14',title:'Potential on the bisector of a rod',short:'Line · beside its middle · potential',subtitle:'P sits out from the middle of a uniform rod. Each piece adds a number, not an arrow.',kind:'Uniform rod',setup:r`A thin rod of length $L$ carries a uniform charge $Q$, so $\lambda=Q/L$. It lies on the $y$-axis, centred at the origin. Find the potential at $P=(r,0)$, with $r>0$, relative to infinity.`,origin:'At the centre of the rod',alternateOrigin:'At the lower end',coordinate:'P=(r,0)',variable:'y',variableTex:'y',density:'Q/L',densityTex:r`\lambda=\frac{Q}{L}`,dq:'lambda*dy',dqTex:r`dQ=\lambda\,dy`,distance:'sqrt(y^2+r^2)',projection:'1',kernel:'k*lambda/sqrt(y^2+r^2)',kernelTex:r`\frac{k\lambda}{\sqrt{y^2+r^2}}`,integralTex:r`V=k\lambda\int_{-L/2}^{L/2}\frac{dy}{\sqrt{y^2+r^2}}`,result:'2*k*lambda*log((L/2+sqrt(L^2/4+r^2))/r)',resultTex:r`V=2k\lambda\ln\frac{L/2+\sqrt{(L/2)^2+r^2}}{r}`,bounds:['-L/2','L/2'],boundTex:['-L/2','L/2'],element:'dy',elementTex:'dy',elementWrong:['y*dy','L*dy'],dqWrong:[wholeRodCharge('y'),uniformRod('y')],elementHint:'Linear density is charge per length. Multiply λ (C/m) by a tiny length dy (m) to get dQ (C).',distanceWrong:[{expression:'r',message:'r is only the horizontal leg. A piece at height y is √(y² + r²) from P.'},'y+r'],kernelWrong:[{expression:'k*lambda*r/(y^2+r^2)^(3/2)',message:'That is the field integrand, with the extra r/rᵢ from the x-projection. Potential has no cosine, so the power in the denominator is 1/2, not 3/2.'},'k*lambda/(y^2+r^2)'],geometryHint:'r is fixed; y varies along the rod. There is no projection factor. The integrand is just kλ / √(y² + r²).',resultWrong:[{expression:'k*lambda*log((L/2+sqrt((L/2)^2+r^2))/r)',message:'That is the potential of half the rod, from its centre to one end. The other half, mirrored below P’s level, is the same distance from P piece for piece and adds exactly as much: the factor 2 is the two halves.'},{expression:'2*k*lambda*log(L/2+sqrt((L/2)^2+r^2))',message:LOG_OF_LENGTH('r')},{expression:'2*k*lambda/r',message:'That is the field of an infinite line, in volts per metre, not a potential. The potential is a logarithm, and for an infinite line it has no finite value relative to infinity at all.'}],symmetry:scalarSym,worked:[{text:r`Put $y=r\tan\alpha$, as for the field on this bisector: $dy=r\sec^2\alpha\,d\alpha$ and $\sqrt{y^2+r^2}=r\sec\alpha$, so the integrand is $\sec\alpha\,d\alpha$, whose integral is $\ln(\sec\alpha+\tan\alpha)$. Back on the triangle, $\sec\alpha+\tan\alpha=\bigl(y+\sqrt{y^2+r^2}\bigr)/r$: a ratio of lengths, so the logarithm’s argument is a pure number.`,tex:r`\begin{aligned}\int\frac{dy}{\sqrt{y^2+r^2}}&=\int\sec\alpha\,d\alpha\\[1.15em]&=\ln\frac{y+\sqrt{y^2+r^2}}{r}\end{aligned}`},{text:r`Evaluate it at the top end of the rod and subtract its value at the bottom end. At both ends the root is the same length, the distance from $P$ to an end of the rod. A difference of two logarithms is the logarithm of their quotient, and the $r$ under each cancels.`,tex:r`\begin{aligned}V&=k\lambda\ln\frac{L/2+\sqrt{(L/2)^2+r^2}}{r}\\&\quad-k\lambda\ln\frac{-L/2+\sqrt{(L/2)^2+r^2}}{r}\\[0.75em]&=k\lambda\ln\frac{\sqrt{(L/2)^2+r^2}+L/2}{\sqrt{(L/2)^2+r^2}-L/2}\end{aligned}`},{text:r`Multiply the top and the bottom of the quotient by its top. The bottom becomes a difference of two squares, which leaves only $r^2$, and the logarithm of a square is twice the logarithm.`,tex:r`\begin{aligned}&\bigl(\sqrt{(L/2)^2+r^2}-L/2\bigr)\\&\quad\times\bigl(\sqrt{(L/2)^2+r^2}+L/2\bigr)=r^2\\[0.4em]V&=k\lambda\ln\frac{\bigl(L/2+\sqrt{(L/2)^2+r^2}\bigr)^2}{r^2}\\[0.75em]&=2k\lambda\ln\frac{L/2+\sqrt{(L/2)^2+r^2}}{r}\end{aligned}`}],limits:[farV(r`r\gg L:\quad V\sim\frac{kQ}{r}`,'Far away every piece is nearly r from P, so the rod acts as its charge Q gathered at its centre: V approaches kQ/r, one power of distance softer than the field. The error in that is of order (L/r)².'),{id:'infinite',title:'The infinite line has no finite V relative to infinity',prompt:'Hold λ fixed and let L → ∞. What happens to V?',answer:'V diverges; only V(r₁) − V(r₂) is finite',choices:['V diverges; only V(r₁) − V(r₂) is finite','V → 2kλ/r, like the field','V → 0'],explanation:'The field of a growing rod converges to 2kλ/r. The potential does not: V ∼ 2kλ ln(L/r), so |V| grows without end, and V keeps the sign of λ. Only a difference between two finite distances is meaningful, V(r₁) − V(r₂) = 2kλ ln(r₂/r₁).',formula:r`L\to\infty\;(\lambda\text{ fixed}):\quad V\sim 2k\lambda\ln(L/r),\quad |V|\to\infty`,mode:'infinite',reference:'Divergent potential'}],link:{id:'bisector',text:'The field on this same bisector',from:'From the rod’s potential: the field on the same bisector'},gradient:{coord:'x',expected:'k*Q/(r*sqrt((L/2)^2+r^2))',tex:r`\frac{kQ}{r\sqrt{(L/2)^2+r^2}}`,hint:'Differentiate the logarithm with respect to r; the chain rule reaches inside the square root. Minus that derivative is the field on the bisector, the result of the lesson “Field on the bisector of a rod”.',wrong:[{expression:'-k*Q/(r*sqrt((L/2)^2+r^2))',message:'E = −∇V points from high potential to low. A positive rod’s field at P points away, along +x.'},{expression:'2*k*lambda/r',message:'That is the infinite-line field, the L → ∞ limit of this derivative, not the finite rod.'},{expression:'k*Q/r^2',message:'That is only the far-field limit, r ≫ L. Up close the rod’s length still matters.'}],worked:[{text:r`On the bisector, symmetry leaves $\mathbf E$ with only its $x$ part, so that part is the whole field there. $V$ known only on the bisector cannot give $\mathbf E$ off it. Start from the quotient of the evaluation, before it was squared. Its root, $\sqrt{(L/2)^2+r^2}$, is the distance from $P$ to either end, and the chain rule gives it the factor $r/\sqrt{(L/2)^2+r^2}$. The logarithm of a quotient differentiates to the top’s derivative over the top, minus the bottom’s over the bottom. Over a common denominator, the bottom is the difference of squares that came to $r^2$.`,tex:r`\begin{aligned}\frac{dV}{dr}&=\frac{k\lambda\,r/\sqrt{(L/2)^2+r^2}}{\sqrt{(L/2)^2+r^2}+L/2}\\&\quad-\frac{k\lambda\,r/\sqrt{(L/2)^2+r^2}}{\sqrt{(L/2)^2+r^2}-L/2}\\[1.15em]&=\frac{k\lambda\,r}{\sqrt{(L/2)^2+r^2}}\cdot\frac{-L}{r^2}\\[1.15em]&=-\frac{k\lambda L}{r\sqrt{(L/2)^2+r^2}}\end{aligned}`},{text:r`The field is minus that derivative. Write $\lambda L$ as $Q$, and it is the bisector field you built from arrows.`,tex:r`E_x=-\frac{dV}{dr}=\frac{kQ}{r\sqrt{(L/2)^2+r^2}}`}]}});
export const vRodAxial=makeV({id:'v-rod-axial',geometry:'axial',number:'15',title:'Potential beyond the end of a rod',short:'Line · on axis · potential',subtitle:'P lies on the rod’s own line, past one end. Each piece adds a number, and every piece adds with the same sign.',kind:'Uniform rod',setup:r`A uniformly charged rod runs from $x=0$ to $x=L$. Point $P$ is at $x=L+a$, a distance $a>0$ beyond the right end. The rod carries a fixed total charge $Q$, so $\lambda=Q/L$. Find the potential at $P$ relative to infinity.`,origin:'At the rod’s left end',alternateOrigin:'At the rod’s centre',coordinate:'P=(L+a,0)',variable:'x',variableTex:'x',density:'Q/L',densityTex:r`\lambda=Q/L`,dq:'lambda*dx',dqTex:r`dQ=\lambda\,dx`,distance:'L+a-x',projection:'1',kernel:'k*lambda/(L+a-x)',kernelTex:r`\frac{k\lambda}{L+a-x}`,integralTex:r`V=k\lambda\int_0^L\frac{dx}{L+a-x}`,result:'k*lambda*log((a+L)/a)',resultTex:r`V=k\lambda\ln\frac{L+a}{a}`,bounds:['0','L'],boundTex:['0','L'],element:'dx',elementTex:'dx',elementWrong:['L*dx','x*dx'],dqWrong:[wholeRodCharge('x'),uniformRod('x')],elementHint:'A length dx contains charge λ dx. Q is the whole rod’s charge, not a density.',distanceWrong:[{expression:'a+x',message:'That runs along the rod the wrong way: it puts the piece at x = L, the one right next to P, a distance L + a away. With P at L + a and the piece at x, the gap is L + a − x.'},{expression:'a',message:'a is only the gap from the rod’s near end. Every other piece is farther away, up to L + a at the far end.'}],kernelWrong:[{expression:'k*lambda/(L+a-x)^2',message:'That is the field integrand. Potential falls as 1/rᵢ, not 1/rᵢ², so the denominator is the distance, not its square.'},'k*lambda/(a+x)'],geometryHint:'P is at L + a and the piece at x. Subtract: rᵢ = L + a − x. Potential has no projection; the integrand is kλ over that distance.',resultWrong:[{expression:'k*lambda*log(a/(L+a))',message:'The substitution u = L + a − x gives du = −dx, and the minus flips the bounds. The argument of the log is (L + a)/a > 1. A positive rod cannot produce negative potential relative to infinity.'},{expression:'k*lambda*log(L+a)',message:LOG_OF_LENGTH('a')+' The argument is (L + a)/a.'},{expression:'k*Q/a',message:'That treats the whole rod as a point charge at its near end. Only far away, a ≫ L, does V approach kQ/a.'}],symmetry:scalarSym,worked:[{text:r`$k\lambda$ is the same for every piece, so it comes outside the integral.`,tex:r`V=k\lambda\int_0^L\frac{dx}{L+a-x}`},{text:r`Let $u=L+a-x$, the piece’s distance from $P$. Then $du=-dx$, and as $x$ runs from $0$ to $L$, $u$ runs from $L+a$ down to $a$: the minus turns the ends round.`,tex:r`V=k\lambda\int_{L+a}^{a}\frac{-du}{u}=k\lambda\int_a^{L+a}\frac{du}{u}`},{text:r`The integral of $1/u$ between two ends is the logarithm of their ratio, $\int_a^b du/u=\ln(b/a)$, a pure number.`,tex:r`V=k\lambda\int_a^{L+a}\frac{du}{u}=k\lambda\ln\frac{L+a}{a}`},{text:r`For $a\gg L$, $\ln(1+L/a)\approx L/a-L^2/(2a^2)$, so $V\approx(kQ/a)\bigl(1-L/(2a)\bigr)\approx kQ/(a+L/2)$: as if all the charge sat at the rod’s centre. As $a\to0$ the potential diverges as $\ln(L/a)$: the charge you walk onto stays finite, but the potential does not.`,tex:r`V=k\lambda\ln\!\left(1+\frac L a\right)`}],limits:[farV(r`a\gg L:\quad V\sim\frac{kQ}{a+L/2}`,'With total charge fixed, the rod’s size becomes negligible and V approaches a point charge’s kQ/d. Measured from the rod’s centre, d = a + L/2, the point-charge form is off only by a term of order (L/a)²; measured from the near end, a, the error falls only as L/a.'),{id:'near',title:'Touching the rod is a logarithmic singularity',prompt:'What happens to V as a → 0, approaching the rod’s end?',answer:'V diverges as ln(L/a)',choices:['V diverges as ln(L/a)','V → kQ/L','V → 0'],explanation:'Each piece’s potential is k dQ/rᵢ. Summed along the line, ∫du/u is a logarithm, ln((L + a)/a), which diverges as the near end, u = a, goes to 0. So as P walks onto the end of the rod, V ∼ kλ ln(L/a): |V| → ∞, and V keeps the sign of λ. The field diverges faster, as 1/a.',formula:r`a\to0:\quad V\sim k\lambda\ln(L/a),\quad |V|\to\infty`,mode:'near',reference:'Endpoint singularity'}],link:{id:'axial',text:'The field beyond this same rod',from:'From the potential beyond the rod: the field at the same P'},gradient:{coord:'x',expected:'k*lambda*(1/a-1/(a+L))',tex:r`k\lambda\left(\frac1a-\frac1{L+a}\right)`,hint:'Differentiate V = kλ ln((L + a)/a) with respect to a. Eₓ = −dV/da is the field beyond the end, the result of the lesson “Field beyond the end of a rod”.',wrong:[{expression:'-k*lambda*(1/a-1/(L+a))',message:'E = −dV/da, not +dV/da. Beyond a positive rod V falls as a grows, so the field points away from the rod, along +x.'},{expression:'k*lambda*log((L+a)/a)',message:'That is V itself, not its derivative. Differentiating ln((L + a)/a) with respect to a gives −L/(a(L + a)).'},{expression:'k*Q/a^2',message:'That treats the rod as a point charge at its near end. The exact field is kQ/(a(L + a)), which approaches kQ/a² only for a ≫ L.'}],worked:[{text:r`On the rod’s own line, symmetry leaves $\mathbf E$ with only its part along the line, so that part is the whole field there. $V$ known only on the line cannot give $\mathbf E$ off it. The logarithm of a quotient differentiates to the top’s derivative over the top, minus the bottom’s over the bottom: here $1/(L+a)-1/a$.`,tex:r`\frac{dV}{da}=k\lambda\left(\frac1{L+a}-\frac1a\right)`},{text:r`The field is minus that derivative: the axial field you built from arrows, equivalently $kQ/(a(L+a))$.`,tex:r`E_x=k\lambda\left(\frac1a-\frac1{L+a}\right)`}]}});

